import type { TestDef } from './types';

// ─────────────────────────────────────────────────────────────────────────
// Human Capital & Social Development Officer (Cell level, reports to the
// Executive Secretary), Level 9.II, Under Contract. Posted identically
// across many districts (not tied to one district here). Exams: Psychometric
// + Written + Oral. Qualifications accepted span almost any field — a
// generalist entry-level post — so content focuses on general public-service
// and social-development-programme knowledge plus the psychometric domains
// the posting itself lists, not on one narrow technical specialism.
// ─────────────────────────────────────────────────────────────────────────

const PROFESSION = { slug: 'human-capital-social-development-officer', name: 'Human Capital & Social Development Officer' };
const DEADLINE = '2026-10-26';

// ───────────────────────────── Mock 1: Social protection & beneficiary targeting

const SP1 = 'Social protection, VUP and Ubudehe';
const SP2 = 'Beneficiary identification and sustainable graduation';
const SP3 = 'Civil service values and professional conduct';
const SP4 = 'General numerical and data reasoning';

export const hcsdMock1: TestDef = {
  country: 'RW',
  jobDeadlineAt: DEADLINE,
  category: 'government-administration',
  profession: PROFESSION,
  authority: 'MINALOC',
  slug: 'human-capital-social-development-officer-mock-exam-1',
  title: 'Human Capital & Social Development Officer — Mock Exam 1',
  summary: 'Practice for this Cell-level social-development post: the Vision 2020 Umurenge Programme (VUP), Ubudehe categorisation, beneficiary targeting and graduation, and civil-service conduct.',
  free: false,
  difficulty: 'STANDARD',
  minutes: 120,
  sections: [{ name: SP1 }, { name: SP2 }, { name: SP3 }, { name: SP4 }],
  questions: [
    { section: SP1, topic: SP1, stem: 'What is the Vision 2020 Umurenge Programme (VUP) primarily designed to do?', options: ['Fund large infrastructure projects only', 'Serve as an integrated local development programme targeting poverty eradication, rural growth and social protection', 'Replace Ubudehe categorisation entirely', 'Provide loans only to registered cooperatives'], correct: 1, explanation: 'VUP is an integrated local development programme aimed at accelerating poverty eradication, rural growth and social protection, targeting households with limited access to assets and income.' },
    { section: SP1, topic: SP1, stem: 'Which ministry-linked agency implements VUP, using Ubudehe as its targeting tool?', options: ['Rwanda Revenue Authority', 'LODA (the Local Administrative Entities Development Agency), under MINALOC', 'Rwanda Development Board', 'National Bank of Rwanda'], correct: 1, explanation: 'VUP is implemented through LODA, which operates under the Ministry of Local Government (MINALOC), using Ubudehe categorisation as its main targeting tool.' },
    { section: SP1, topic: SP1, stem: 'Rwanda’s Ubudehe categorisation system currently groups households into how many categories, labelled with letters?', options: ['Three categories, A to C', 'Four categories, numbered 1 to 4', 'Five categories, A to E', 'Six categories, A to F'], correct: 2, explanation: 'Ubudehe was revised from four numbered categories to five lettered categories, A through E, with A being the highest-income group and E a special category.' },
    { section: SP1, topic: SP1, stem: 'What is the main purpose of Ubudehe categorisation?', options: ['To rank schools by exam results', 'To socially stratify households mainly by income/wealth level, to target social programmes appropriately', 'To register land titles', 'To assign civil servants to districts'], correct: 1, explanation: 'Ubudehe is a social stratification scheme based primarily on household income/wealth, used to target social protection and other programmes to those who need them most.' },
    { section: SP1, topic: SP1, stem: 'A household’s circumstances improve substantially over two years of VUP support. What should happen next under the programme’s own logic?', options: ['Nothing — VUP support never changes once granted', 'The household should be re-assessed, and if it meets the criteria, it should "graduate" to a higher Ubudehe category and exit VUP support', 'The household should be removed from all district records', 'The household should automatically become a VUP official'], correct: 1, explanation: 'VUP is built around a national strategy for sustainable graduation: beneficiaries are reassessed, and improved circumstances should move them to a higher Ubudehe category and off VUP support, freeing resources for others still in need.' },
    { section: SP1, topic: SP1, stem: 'Which of these is a core component commonly associated with VUP’s approach to supporting the poorest households?', options: ['Direct cash transfers and public-works employment for those able to work', 'Compulsory military service', 'Free international scholarships for all participants', 'Automatic land redistribution'], correct: 0, explanation: 'VUP combines elements such as direct support (cash transfers) for households unable to work and public-works employment for those who are able to work, among other components.' },
    { section: SP1, topic: SP1, stem: 'A social development officer notices a household is still classified in the lowest Ubudehe category despite having visibly higher income than before (e.g. a new permanent house and livestock). What is the most appropriate action?', options: ['Ignore it, since categorisation is permanent', 'Report the discrepancy through the proper community Ubudehe review process so the classification can be reassessed', 'Personally reclassify the household on the spot', 'Tell the household to hide the new assets'], correct: 1, explanation: 'Ubudehe classification is a community-based, periodically reviewed process; an officer noticing a likely discrepancy should raise it through that proper review channel, not reclassify unilaterally or encourage concealment.' },
    { section: SP1, topic: SP1, stem: 'Why is accurate, up-to-date community data important for VUP and Ubudehe targeting?', options: ['It is not important; targeting uses fixed historical data only', 'Inaccurate data could mean support reaches households that no longer need it while genuinely vulnerable households are missed', 'It is only needed for annual national statistics, not local targeting', 'Data accuracy only matters for urban areas'], correct: 1, explanation: 'Social protection targeting depends on current household circumstances; stale or inaccurate data risks misallocating support, which undermines both fairness and the programme’s poverty-reduction goal.' },
    { section: SP1, topic: SP1, stem: 'What role does the Cell level typically play in VUP and Ubudehe implementation?', options: ['None — these programmes are run entirely from the national level with no local involvement', 'Front-line monitoring, data collection, community mobilisation and support for the categorisation and beneficiary-identification process', 'Setting the national VUP budget', 'Approving international VUP funding agreements'], correct: 1, explanation: 'Cell-level staff are typically closest to households and play a front-line role in monitoring, data collection, community mobilisation and supporting the categorisation and targeting process that feeds into district and national systems.' },
    { section: SP1, topic: SP1, stem: 'Which best describes the relationship between poverty graduation and sustainable development goals at the local level?', options: ['They are unrelated', 'Successful graduation out of extreme poverty supports broader human-capital and social-development goals by freeing households to invest in education, health and livelihoods', 'Graduation only matters for the national budget, not for communities', 'Graduation is purely a statistical exercise with no real-world effect'], correct: 1, explanation: 'When households sustainably exit extreme poverty, they are better able to invest in their children’s education, health and livelihoods, reinforcing the broader human-capital development goals a social development officer supports.' },
    { section: SP1, topic: SP1, stem: 'A new VUP cash-transfer cycle is about to start. What should a social development officer verify before transfers are confirmed for a given household?', options: ['Nothing, transfers are automatic once a household is ever registered', 'That the household’s current Ubudehe category and registration details are accurate and up to date', 'Only the household head’s name, nothing else', 'The household’s religious affiliation'], correct: 1, explanation: 'Because targeting depends on current, accurate household data, verifying the Ubudehe category and registration details before confirming transfers helps ensure support reaches the right households.' },
    { section: SP1, topic: SP1, stem: 'Which statement about VUP public-works components is most accurate?', options: ['They provide paid work on community infrastructure or services to able-bodied members of poor households, alongside direct support for those unable to work', 'They are unrelated to poverty reduction', 'They replace the need for Ubudehe categorisation', 'They are only available to civil servants'], correct: 0, explanation: 'VUP’s public-works component creates paid work opportunities (often on community infrastructure) for able-bodied members of poor households, complementing direct support for households that cannot provide labour.' },
    { section: SP1, topic: SP1, stem: 'Why might a social development officer need to coordinate with both the Sector and the District on VUP matters, rather than acting purely at Cell level?', options: ['Because VUP budgets, broader monitoring and reporting flow up through the Sector to the District and beyond, so Cell-level work must feed into that chain', 'Because the Cell has no connection to the Sector or District at all', 'Because VUP is managed entirely by the national government with no Cell, Sector or District role', 'Coordination is never required'], correct: 0, explanation: 'Rwanda’s decentralised system means Cell-level data and implementation feed upward through the Sector to the District, so coordination across these levels is necessary for coherent VUP delivery and reporting.' },
    { section: SP1, topic: SP1, stem: 'A community member complains that a neighbour receiving VUP support appears, in their view, wealthier than they are. What is the appropriate first step?', options: ['Publicly confront the neighbour', 'Note the complaint and refer it through the established community/Ubudehe review mechanism for proper assessment, rather than act on the complaint alone', 'Immediately cut off the neighbour’s support', 'Dismiss the complaint without record'], correct: 1, explanation: 'Individual complaints should be channelled through the established review process so classification decisions are based on a proper assessment, not on unverified claims or unilateral action.' },
    { section: SP1, topic: SP1, stem: 'What is a key reason social protection programmes like VUP are linked to broader human-capital goals, rather than treated as a standalone welfare measure?', options: ['They have no link to human capital', 'Relieving extreme poverty supports better nutrition, school attendance and health outcomes for children in supported households, which builds future human capital', 'Human capital only concerns university graduates', 'Social protection and human capital are managed by entirely separate, unconnected ministries with no coordination'], correct: 1, explanation: 'By relieving extreme poverty, social protection programmes help create conditions (adequate nutrition, ability to stay in school, access to healthcare) that support children’s long-term development — directly reinforcing human-capital goals.' },
    { section: SP1, topic: SP1, stem: 'Which of the following is NOT typically a direct responsibility of VUP/Ubudehe-related work at Cell level?', options: ['Supporting household data collection and verification', 'Participating in community mobilisation around the Ubudehe process', 'Setting Rwanda’s national monetary policy', 'Monitoring whether support reaches intended beneficiaries'], correct: 2, explanation: 'Setting national monetary policy is the responsibility of the National Bank of Rwanda, not a Cell-level social development officer, whose VUP/Ubudehe-related duties are data collection, mobilisation and monitoring at the local level.' },
    { section: SP1, topic: SP1, stem: 'A district reports that several VUP-supported households have had no follow-up visit in over a year. What is the most likely consequence of this gap?', options: ['No consequence; follow-up is purely optional paperwork', 'Outdated information on household circumstances, risking continued support for households that may have already graduated, or missed support for households whose situation has worsened', 'An automatic increase in the national VUP budget', 'Immediate suspension of the whole VUP programme nationally'], correct: 1, explanation: 'Without regular follow-up, a household’s recorded circumstances can drift out of date, risking misallocated support in either direction — continuing it for households that no longer need it, or missing households whose situation has worsened.' },
    { section: SP1, topic: SP1, stem: 'Which best describes "sustainable graduation" in the VUP/Ubudehe context?', options: ['A household exiting poverty support in a way that is durable, because its underlying circumstances (assets, income, skills) have genuinely improved, not just a temporary change', 'Any household leaving the programme for any reason', 'A household moving to a different district', 'A one-time cash bonus with no further monitoring'], correct: 0, explanation: 'Sustainable graduation means a household’s exit from poverty support reflects a durable improvement in its underlying circumstances, not a temporary fluctuation that could see it fall back into needing support.' },
    { section: SP1, topic: SP1, stem: 'Why is coordinating Ubudehe data collection with other social-protection-relevant data (such as education or health records) valuable at Cell level?', options: ['It has no value; each data source should remain entirely separate', 'A fuller picture of a household’s circumstances across different domains supports more accurate targeting and more effective, coordinated support', 'It is only useful for generating extra paperwork', 'Combining records is prohibited by policy in all cases'], correct: 1, explanation: 'Looking across domains — income, education, health — gives a fuller, more accurate picture of a household’s real circumstances, supporting better-targeted and more coordinated support, which is part of the officer’s monitoring role.' },
    { section: SP1, topic: SP1, stem: 'A colleague suggests skipping the standard verification steps for a VUP applicant "to save time," since the applicant is a relative of a local leader. What should the officer do?', options: ['Agree, since the applicant is likely eligible anyway', 'Follow the standard verification process for every applicant regardless of personal connections, and raise the suggestion to skip steps if it continues', 'Approve it quietly without telling anyone', 'Reject the application automatically because of the connection'], correct: 1, explanation: 'Standard verification exists to ensure support is fairly and accurately targeted; applying it inconsistently based on personal connections undermines the programme’s integrity, so the officer should follow the process and flag pressure to bypass it.' },
    { section: SP1, topic: SP1, stem: 'A resident who is self-employed with a seasonally variable income asks why their Ubudehe category seems inconsistent year to year. What is the most accurate explanation?', options: ['Categorisation is random', 'Ubudehe assessments are periodically reviewed and reflect current circumstances, so genuine changes in income or assets can shift a household’s category over time', 'Categories never change once assigned', 'Self-employed people are automatically excluded from Ubudehe'], correct: 1, explanation: 'Because Ubudehe categorisation is reviewed periodically and reflects current circumstances, genuine year-to-year changes in income or assets can reasonably shift a household’s category.' },
    { section: SP1, topic: SP1, stem: 'Why might VUP combine both direct cash support and public-works employment, rather than using only one approach?', options: ['To make the programme more complicated for no reason', 'Because households differ in their capacity to work — some members can work and benefit from public-works income, while others (such as those unable to work) need direct support instead', 'Public works and cash support are actually the same thing', 'Only one approach is ever used in practice'], correct: 1, explanation: 'Combining the two approaches lets the programme respond to different household circumstances — public works suits those who can work, while direct support reaches those who cannot, such as some elderly or severely disabled household members.' },
    { section: SP1, topic: SP1, stem: 'What is a reasonable first step if a social development officer suspects that VUP registration data for several households in the Cell has not been updated in a long time?', options: ['Wait for someone else to notice', 'Flag the gap to the relevant supervisor and prioritise a verification/update exercise for those records', 'Quietly delete the old records', 'Assume the data is still accurate without checking'], correct: 1, explanation: 'Flagging the gap and prioritising verification keeps targeting accurate, rather than silently deleting records or assuming outdated data is still correct.' },
    { section: SP1, topic: SP1, stem: 'In what sense is Ubudehe described as a "targeting tool" for VUP, rather than a standalone programme?', options: ['Ubudehe has no connection to VUP at all', 'Ubudehe categorisation is used to identify which households VUP and related social-protection programmes should prioritise for support', 'Ubudehe replaces the need for VUP entirely', 'Ubudehe only applies to urban households'], correct: 1, explanation: 'Ubudehe itself is a categorisation/targeting system; VUP and other social-protection programmes use it to identify and prioritise the households most in need of support.' },
    { section: SP1, topic: SP1, stem: 'A household disputes its Ubudehe category, believing it should be placed in a lower (poorer) category. What is the appropriate process?', options: ['Immediately change the category to whatever the household requests', 'Direct the household through the established community review/appeal process so the claim can be properly assessed', 'Ignore the dispute entirely', 'Tell the household categories cannot ever be disputed'], correct: 1, explanation: 'Disputes should go through the established community-based review process, which allows a proper assessment rather than an unverified change based solely on the household’s own claim.' },
    { section: SP2, topic: SP2, stem: 'What is meant by "beneficiary identification" in the context of social-protection programmes?', options: ['Randomly selecting households from a national list', 'The structured process of determining which households meet the eligibility criteria for a given programme, typically using tools such as Ubudehe categorisation and household registers', 'A once-only national census with no local input', 'A purely automated process with no human verification'], correct: 1, explanation: 'Beneficiary identification is the structured, criteria-based process of determining which households qualify for a programme, drawing on tools such as Ubudehe categorisation and community/household registers, typically verified at the local level.' },
    { section: SP2, topic: SP2, stem: 'Why are community registers an important tool for beneficiary identification at Cell level?', options: ['They have no real use beyond record-keeping for its own sake', 'They provide a local, continuously updatable record of households and their circumstances that supports accurate, current targeting of support', 'They exist only to satisfy an audit requirement with no operational use', 'They replace the need for any direct community engagement'], correct: 1, explanation: 'Community registers give Cell-level officers an ongoing, locally grounded record of households, which supports more accurate and up-to-date targeting than relying solely on infrequent national surveys.' },
    { section: SP2, topic: SP2, stem: 'A household was eligible for a social-protection programme two years ago but has since had a family member start stable employment. What should happen to its status?', options: ['Nothing; eligibility is permanent once granted', 'Its circumstances should be reassessed, and its support/category adjusted if it no longer meets the original eligibility criteria', 'The household should be penalised for the change in circumstances', 'The whole household should be removed from all district records'], correct: 1, explanation: 'Eligibility for social protection should reflect current circumstances; a genuine improvement (such as stable new employment) is exactly the kind of change that a periodic reassessment is meant to capture.' },
    { section: SP2, topic: SP2, stem: 'What is the main reason "self-reporting" by applicants alone is not considered sufficient for beneficiary identification?', options: ['Self-reporting is actually always sufficient on its own', 'Self-reported information can be inaccurate or incomplete, whether unintentionally or not, so independent verification (e.g. community knowledge, field visits, cross-checked records) improves accuracy and fairness', 'Self-reporting is illegal', 'Only written, notarised documents are ever accepted for any purpose'], correct: 1, explanation: 'Because self-reported information can be inaccurate for many reasons, independent verification — drawing on community knowledge, field visits and cross-checked records — helps ensure targeting is accurate and fair to all applicants.' },
    { section: SP2, topic: SP2, stem: 'Which of these is most consistent with "sustainable graduation" as a design principle, rather than a one-off support model?', options: ['Giving a single cash payment and no further contact', 'Combining elements such as asset support, skills development and monitored follow-up so households build lasting capacity to sustain improved circumstances', 'Removing support abruptly without warning', 'Providing support only to households that never need to be reassessed'], correct: 1, explanation: 'A sustainable-graduation approach typically combines several elements — such as asset support, skills building, and monitored follow-up — so households develop the lasting capacity to sustain improved circumstances, not just a short-term boost.' },
    { section: SP2, topic: SP2, stem: 'During a household visit, an officer finds information that contradicts what is in the existing community register. What is the appropriate response?', options: ['Ignore the discrepancy and move on', 'Record the discrepancy accurately and follow the proper process to update or verify the register, rather than silently editing it based on a single visit', 'Delete the old record immediately without documentation', 'Assume the household is lying and penalise them'], correct: 1, explanation: 'Discrepancies should be documented and run through the proper verification/update process, preserving a clear record of why and how information changed, rather than being silently edited or assumed to reflect dishonesty.' },
    { section: SP2, topic: SP2, stem: 'A programme has a fixed number of beneficiary slots but more eligible households than slots available in one cycle. What is the fairest general approach?', options: ['First come, first served regardless of need', 'Prioritise based on the programme’s stated eligibility/vulnerability criteria (e.g. Ubudehe category, specific vulnerabilities) applied consistently to all applicants', 'Let the officer choose personal favourites', 'Exclude everyone until more slots appear'], correct: 1, explanation: 'When demand exceeds available slots, consistently applying the programme’s own stated criteria — rather than arbitrary order or personal preference — is the fairest and most defensible way to prioritise among eligible households.' },
    { section: SP2, topic: SP2, stem: 'Why does beneficiary identification typically involve both community-level input (such as local leaders or Ubudehe structures) and official criteria/tools?', options: ['Community input is irrelevant and only official tools matter', 'Community-level knowledge can surface context that official records alone might miss, while official criteria keep the process consistent and defensible', 'Official criteria are irrelevant and only community opinion matters', 'Both are deliberately kept separate and are never combined'], correct: 1, explanation: 'Community-level knowledge helps capture local context and nuance that purely administrative records might miss, while applying official, consistent criteria protects fairness and accountability — the two approaches complement each other.' },
    { section: SP2, topic: SP2, stem: 'What does "data consolidation" mean in the context of monitoring social, health and education programmes at Cell level, as listed among this role’s duties?', options: ['Deleting old data to save storage', 'Collecting data from various sources/activities and combining it into a coherent, accurate overall picture for reporting and decision-making', 'Keeping every data source entirely separate and never comparing them', 'A one-time activity done only at the end of a civil servant’s career'], correct: 1, explanation: 'Data consolidation means gathering information from multiple activities or sources and combining it into an accurate, coherent picture, which supports clearer reporting and better-informed decisions at Cell, Sector and District levels.' },
    { section: SP2, topic: SP2, stem: 'An officer is asked to "assist in identifying eligible beneficiaries using social protection programme tools and community registers to ensure sustainable graduation" (one of this role’s core duties). Which activity best fits this duty?', options: ['Approving the national VUP budget', 'Cross-checking Ubudehe categories and household registers against current circumstances to confirm who should be supported and tracking their progress toward graduation', 'Managing the Rwanda Revenue Authority’s tax collection', 'Setting foreign exchange policy'], correct: 1, explanation: 'This duty is squarely about using the available tools (Ubudehe categorisation, registers) to identify and track beneficiaries toward sustainable graduation — not national budget, tax, or monetary-policy functions, which sit elsewhere.' },
    { section: SP2, topic: SP2, stem: 'Which outcome would most clearly indicate that beneficiary targeting in a Cell is working well?', options: ['A large, growing number of households permanently receiving support with no change over many years', 'Support consistently reaching households that meet the eligibility criteria, with households that have genuinely improved being reassessed and graduating over time', 'No one in the Cell ever being reassessed', 'All households receiving identical support regardless of circumstances'], correct: 1, explanation: 'Good targeting means eligible households are reliably supported and reassessed as circumstances change, with genuine improvement leading to graduation — not a static, unchanging caseload or undifferentiated support for everyone.' },
    { section: SP2, topic: SP2, stem: 'What risk does poor record-keeping create for beneficiary-identification work specifically?', options: ['No real risk; records are a formality', 'Households could be wrongly included or excluded, undermining both fairness to applicants and the programme’s effectiveness', 'Poor records only affect unrelated, unconnected programmes', 'Poor records automatically increase the programme’s budget'], correct: 1, explanation: 'If records are inaccurate or incomplete, eligible households could be missed while ineligible ones continue receiving support, which is both unfair to applicants and undermines the programme’s intended impact.' },
    { section: SP2, topic: SP2, stem: 'What distinguishes a well-run beneficiary-identification process from a poorly-run one, most fundamentally?', options: ['Whether it uses paper or digital forms', 'Whether it consistently and accurately applies eligibility criteria using verified, current information, regardless of the specific tools used', 'Whether it happens quickly, regardless of accuracy', 'Whether it is run entirely by one single person'], correct: 1, explanation: 'The fundamental measure of a good process is consistent, accurate application of eligibility criteria based on verified, current information — the specific tools or speed are secondary to getting this right.' },
    { section: SP2, topic: SP2, stem: 'Why is it important to document the reasoning behind a beneficiary-eligibility decision, not just the final outcome?', options: ['Documentation is unnecessary busywork', 'It supports transparency and accountability, and allows a decision to be reviewed or explained later if questioned', 'Only the final outcome ever matters for any process', 'Documenting reasoning is prohibited by policy'], correct: 1, explanation: 'Recording the reasoning behind a decision supports transparency and accountability, and means the decision can be properly reviewed, explained or appealed later if needed.' },
    { section: SP2, topic: SP2, stem: 'A new household moves into the Cell mid-year. What is the appropriate next step regarding social-protection eligibility?', options: ['Assume they are not eligible for anything since they are new', 'Register and assess the household through the standard process so its eligibility can be properly determined', 'Automatically enrol them in every programme without assessment', 'Wait until the next national census to take any action'], correct: 1, explanation: 'New households should go through the standard registration and assessment process so their eligibility is properly determined, rather than being excluded by default or enrolled without assessment.' },
    { section: SP2, topic: SP2, stem: 'What is a practical benefit of tracking a beneficiary household’s progress over multiple assessment cycles, rather than only assessing it once?', options: ['No benefit; one assessment is always sufficient', 'It reveals trends (improving or worsening circumstances) that support timely decisions about continued support, adjustment, or graduation', 'Tracking is only useful for record-keeping, with no bearing on decisions', 'Multiple assessments are prohibited by policy'], correct: 1, explanation: 'Tracking progress over time reveals whether a household’s circumstances are improving or worsening, which supports timely, well-informed decisions about adjusting or ending support.' },
    { section: SP2, topic: SP2, stem: 'Two households have similar incomes, but one has a member with a disability requiring ongoing care while the other does not. Should this difference matter for targeting, consistent with the role’s "inclusiveness" value?', options: ['No, only income should ever be considered', 'Yes, relevant vulnerabilities such as disability-related needs are a legitimate part of a fuller assessment of a household’s circumstances, consistent with inclusive, needs-based targeting', 'The disability should be hidden from the record', 'Only households with no vulnerabilities should ever receive support'], correct: 1, explanation: 'Needs-based, inclusive targeting considers relevant vulnerabilities such as disability-related care needs alongside income, since these affect a household’s real circumstances and support requirements.' },
    { section: SP2, topic: SP2, stem: 'Which best describes the purpose of periodic "reassessment" in beneficiary management?', options: ['A formality with no real effect on anyone’s support', 'Confirming whether a household still meets eligibility criteria, so support, category or graduation status can be updated as needed', 'A way to permanently remove households from all records', 'A one-time check done only when a programme first launches'], correct: 1, explanation: 'Reassessment exists to confirm whether circumstances still match the original eligibility basis, allowing support levels, categories or graduation status to be updated to reflect reality.' },
    { section: SP2, topic: SP2, stem: 'An officer has incomplete information about a household applying for support. What is the most responsible approach?', options: ['Guess and approve the application anyway', 'Seek the missing information through proper verification before finalising the eligibility decision', 'Reject the application automatically due to incompleteness, with no attempt to gather more information', 'Approve it and worry about verification later, if ever'], correct: 1, explanation: 'Seeking the missing information through proper verification, rather than guessing or rejecting outright, supports accurate and fair eligibility decisions.' },
    { section: SP2, topic: SP2, stem: 'Why might cross-referencing Ubudehe data against school enrolment or health-centre attendance records help with sustainable-graduation tracking?', options: ['These records are entirely unrelated to graduation', 'Such records can offer independent indicators of a household’s real circumstances and whether children’s outcomes are improving alongside household income, enriching the picture beyond income data alone', 'Cross-referencing different data sources is prohibited', 'Only income data should ever be used, by policy'], correct: 1, explanation: 'Indicators like school enrolment or health-centre attendance can independently reflect whether a household’s overall wellbeing is genuinely improving, complementing income-based assessment for a fuller graduation picture.' },
    { section: SP2, topic: SP2, stem: 'What is a reasonable way to handle a beneficiary household that cannot be located during a scheduled verification visit?', options: ['Immediately assume fraud and remove them from all records', 'Record the missed visit, attempt follow-up through other means (such as neighbours or local leaders), and avoid any final decision until genuine effort has been made to reach them', 'Ignore the missed visit entirely', 'Automatically increase their support level'], correct: 1, explanation: 'A missed visit should be documented and followed up on reasonably before any conclusion is drawn, rather than jumping to assumptions of fraud or ignoring the gap altogether.' },
    { section: SP2, topic: SP2, stem: 'A household’s Ubudehe category has remained unchanged for five years despite the officer’s field observations suggesting real improvement. What should the officer do?', options: ['Assume the category must be correct since it has not changed', 'Flag the household for reassessment, since field observations suggesting a real change are exactly the kind of signal that should trigger a review', 'Change the category immediately without any formal process', 'Do nothing, since reassessment only happens automatically on a fixed schedule'], correct: 1, explanation: 'Field observations suggesting a real change in circumstances are a legitimate reason to flag a household for formal reassessment, rather than assuming the existing category must still be accurate.' },
    { section: SP2, topic: SP2, stem: 'Why is it important that beneficiary-identification criteria be applied the same way across every household in a Cell?', options: ['Consistency has no real importance', 'Applying criteria consistently is central to fairness, and inconsistent application risks both excluding genuinely eligible households and including ineligible ones', 'Criteria should actually vary household by household based on the officer’s personal judgement alone', 'Consistency only matters for programmes funded internationally'], correct: 1, explanation: 'Consistent application of eligibility criteria is central to fair, defensible targeting; inconsistency risks unfairly excluding eligible households or including ineligible ones.' },
    { section: SP2, topic: SP2, stem: 'A colleague proposes enrolling an entire village automatically in a support programme without individual assessment, to "save time." What is the main problem with this approach?', options: ['There is no problem; blanket enrolment is always best', 'It would mean support is not actually targeted to those who meet the eligibility criteria, undermining fairness and the programme’s intended impact', 'It would take longer than individual assessment', 'Individual assessment is never required by any programme'], correct: 1, explanation: 'Blanket enrolment without assessment abandons the whole purpose of targeted eligibility criteria, risking support going to households that do not need it while straining resources meant for those who do.' },
    { section: SP2, topic: SP2, stem: 'What is the relationship between accurate community registers and effective reporting up to the Sector and District levels?', options: ['There is no relationship; reporting uses entirely separate data', 'Accurate Cell-level registers are the foundation that higher-level reports and planning rely on, so errors at Cell level can distort decisions made at Sector or District level', 'Reporting only uses national census data, never local registers', 'Community registers are irrelevant to any reporting'], correct: 1, explanation: 'Since data flows upward from Cell-level registers into Sector and District reporting and planning, inaccuracies at the Cell level can distort the information decision-makers rely on further up the chain.' },
    { section: SP2, topic: SP2, stem: 'A household has two children attending a social protection-linked programme, but one child stopped attending months ago without the household reporting it. What should the officer do upon discovering this?', options: ['Ignore it since the household did not report it themselves', 'Follow up with the household to understand the reason, update the relevant records, and connect them with appropriate support if needed', 'Automatically remove the household from all programmes as punishment', 'Assume the information is false without checking'], correct: 1, explanation: 'Following up to understand the situation, updating records, and connecting the household with appropriate support reflects both accurate monitoring and a citizen-focused, supportive approach — rather than punitive assumptions.' },
    { section: SP3, topic: SP3, stem: 'The job posting lists "client/citizen focus" as a required competency. What does this mean in day-to-day practice for this role?', options: ['Prioritising personal convenience over residents’ needs', 'Prioritising responsiveness and quality service to the Cell’s residents when carrying out social-development duties', 'Avoiding contact with citizens whenever possible', 'Treating citizen requests as a low priority compared to paperwork'], correct: 1, explanation: 'Client/citizen focus means putting residents’ needs at the centre of how the job is done — being responsive and providing quality service — rather than treating citizens as an afterthought to administrative tasks.' },
    { section: SP3, topic: SP3, stem: 'What is the practical meaning of "accountability" as a civil-service value for this role?', options: ['Avoiding any responsibility for outcomes', 'Taking ownership of one’s duties and their outcomes, and being answerable for decisions and actions taken in the role', 'Blaming colleagues for any shortfall', 'Only being accountable to oneself, not to supervisors or citizens'], correct: 1, explanation: 'Accountability means owning the outcomes of one’s work and being answerable — to supervisors, the institution and the citizens served — for decisions and actions taken while carrying out official duties.' },
    { section: SP3, topic: SP3, stem: 'A resident offers a social development officer a personal gift in exchange for being moved up the VUP beneficiary list. What is the correct response, consistent with integrity as a required competency?', options: ['Accept the gift quietly since it is a personal matter', 'Decline the gift, explain that eligibility is based on official criteria, and report the offer through the proper channel', 'Accept the gift and move the resident up informally', 'Ask for a larger gift before considering it'], correct: 1, explanation: 'High integrity and professional ethical standards require declining any attempt to influence an official decision improperly, explaining that eligibility follows official criteria, and reporting the incident appropriately.' },
    { section: SP3, topic: SP3, stem: 'What does "inclusiveness," listed among the required competencies, mean in the context of delivering services to youth, women and people with disabilities (duties explicitly listed for this role)?', options: ['Focusing exclusively on one group and excluding others', 'Ensuring that different groups in the community — including youth, women and people with disabilities — are genuinely considered and able to access relevant programmes and services', 'Treating inclusiveness as a slogan with no practical application', 'Avoiding any specific programmes for particular groups'], correct: 1, explanation: 'Inclusiveness here means actively ensuring that groups such as youth, women and people with disabilities are genuinely considered in programme delivery and can access the services and support relevant to them, not just formally listed as a value.' },
    { section: SP3, topic: SP3, stem: 'Why does the role require "digital literacy skills," given the duties listed (data collection, reporting via information management systems)?', options: ['Digital tools are irrelevant to this role', 'Because reporting and data consolidation are done through information management systems, requiring comfort with digital tools to do the job effectively', 'Digital literacy is only relevant for IT staff', 'The role involves no data or reporting work at all'], correct: 1, explanation: 'Since the role explicitly involves collecting and consolidating data and reporting through information management systems, digital literacy is a practical requirement for carrying out these core duties effectively.' },
    { section: SP3, topic: SP3, stem: 'What is the best description of "professionalism" as expected of this role?', options: ['Acting however one personally prefers regardless of official standards', 'Carrying out duties competently, ethically and respectfully, in line with the standards expected of a civil servant', 'Avoiding any interaction with the public', 'Prioritising personal opinions over official policy'], correct: 1, explanation: 'Professionalism means carrying out one’s duties competently, ethically and respectfully, consistent with the standards expected of someone representing the local administration in their daily work.' },
    { section: SP3, topic: SP3, stem: 'The posting requires working with "minimal supervision to efficiently meet deadlines" under a "complex and multi-faceted workload." What does this suggest about how the role should be approached?', options: ['Waiting for explicit instructions before doing anything', 'Managing one’s own time and priorities proactively across varied duties, without needing constant direction, to meet deadlines reliably', 'Working on only one task at a time and ignoring all others', 'Delegating all responsibilities to a supervisor'], correct: 1, explanation: 'Being results-oriented under minimal supervision means proactively managing one’s own time and priorities across a varied workload, rather than waiting for step-by-step direction, in order to reliably meet deadlines.' },
    { section: SP3, topic: SP3, stem: 'A social development officer is asked by a supervisor to omit an unfavourable finding from a Cell-level report. What is the professionally correct response?', options: ['Omit it, since the supervisor asked', 'Present the finding accurately and raise any concerns about how to frame or address it, rather than omit it from the report', 'Resign immediately without discussion', 'Publicly announce the finding on social media'], correct: 1, explanation: 'Accurate reporting is essential to accountability and effective decision-making; the professional response is to report the finding accurately while discussing, through proper channels, how it should be framed or addressed — not to simply omit it.' },
    { section: SP3, topic: SP3, stem: 'Why is "knowledge and understanding of Local Government functioning" (a listed competency) important for this role?', options: ['It is irrelevant background information', 'The role sits within, and must coordinate across, the Cell-Sector-District structure, so understanding how local government works supports effective performance of the job', 'Local government structures have no bearing on day-to-day duties', 'This competency only matters for elected officials, not appointed staff'], correct: 1, explanation: 'Because the role’s duties involve reporting, coordination and support for District-level plans within the Cell-Sector-District structure, understanding how local government functions is directly relevant to doing the job effectively.' },
    { section: SP3, topic: SP3, stem: 'Which best reflects "continuous learning" as a competency for this role, given its broad range of duties (education, health, social protection, youth programmes, and more)?', options: ['Assuming initial training is sufficient forever', 'Actively keeping up to date with changes in the various programmes and policies the role touches, since the duties span many different sectors', 'Avoiding any further training once hired', 'Relying only on personal opinion rather than updated guidance'], correct: 1, explanation: 'Given the breadth of this role — spanning social protection, education, health, youth and more — actively keeping knowledge current as policies and programmes evolve is essential to performing the duties well.' },
    { section: SP3, topic: SP3, stem: 'What does "risk and resource management skills," listed among this role’s competencies, most practically involve?', options: ['Ignoring risks entirely to save time', 'Anticipating problems (such as data gaps, missed deadlines or resource shortfalls) and managing available resources (time, budget, information) to address duties effectively', 'Only applying to financial staff, not this role', 'Taking on unlimited risk regardless of consequences'], correct: 1, explanation: 'In this role, risk and resource management means anticipating practical problems and managing the time, information and resources available to carry out the varied duties effectively.' },
    { section: SP3, topic: SP3, stem: 'A social development officer is asked to help organise a community mobilisation campaign on short notice. What best reflects "time management skills" in this situation?', options: ['Refusing the task because it was not planned in advance', 'Prioritising tasks, adjusting the schedule where possible, and communicating realistically about what can be delivered within the available time', 'Dropping all other duties with no communication to anyone', 'Doing the campaign poorly without any planning'], correct: 1, explanation: 'Good time management under a short deadline means prioritising, adjusting where possible, and communicating clearly about what can realistically be delivered — not refusing the task or abandoning other duties without explanation.' },
    { section: SP3, topic: SP3, stem: 'The posting lists fluency in "Kinyarwanda, English and/or French" as an advantage. Why would multilingual ability be practically useful in this role?', options: ['It has no practical use', 'It supports clearer communication with residents, local leaders and various stakeholders or documents the role may encounter', 'Only one language is ever used in any official context', 'Multilingual ability is only relevant for translators'], correct: 1, explanation: 'Since the role involves direct engagement with citizens and coordination across levels of government, being able to communicate clearly in the languages commonly used supports more effective service delivery.' },
    { section: SP3, topic: SP3, stem: 'What is the best description of "reporting and writing skills" as applied to this role’s duties?', options: ['An irrelevant soft skill', 'The ability to clearly and accurately document findings, data and recommendations using the information management systems and formats expected at Cell/Sector/District level', 'Only relevant to employees in communications departments', 'The ability to write long reports regardless of clarity or accuracy'], correct: 1, explanation: 'Given the duties around data collection, consolidation and reporting, the ability to document findings clearly and accurately — not just at length — is directly relevant to doing the job well.' },
    { section: SP3, topic: SP3, stem: 'A resident raises a complaint about how a social programme is being implemented in the Cell. What best reflects "communication and engagement with citizens" as a required competency?', options: ['Dismissing the complaint without response', 'Listening to the complaint, responding respectfully, and following up through the appropriate process', 'Responding only if the complaint is submitted in writing and notarised', 'Referring every complaint to the national government regardless of its nature'], correct: 1, explanation: 'Genuine citizen engagement means listening respectfully, responding appropriately, and following up through the right process — not dismissing concerns or imposing unnecessary barriers to raising them.' },
    { section: SP3, topic: SP3, stem: 'Why does this role require both "analytical skills" and "leadership skills," given that it sits at Cell level rather than a senior management level?', options: ['These skills are irrelevant at Cell level', 'The role requires interpreting data/situations to inform action (analytical) and taking initiative to mobilise community support and coordinate activities (leadership), even without formal managerial authority', 'Only senior officials ever need these skills', 'Analytical and leadership skills mean the same thing in this context'], correct: 1, explanation: 'Even without formal managerial authority, the role requires analysing information to guide action and showing initiative in mobilising and coordinating community activities — both of which draw on analytical and leadership capability.' },
    { section: SP3, topic: SP3, stem: 'What is the best interpretation of "strongly results-oriented" as applied to this role’s complex, multi-faceted workload?', options: ['Focusing only on activity, regardless of whether it achieves anything', 'Focusing on achieving genuine outcomes (such as accurate targeting, timely reports, effective mobilisation) across the varied duties, not just completing tasks for their own sake', 'Avoiding any responsibility for outcomes', 'Results-orientation only matters for one specific duty, not the whole role'], correct: 1, explanation: 'Being results-oriented means focusing on achieving genuine outcomes across the role’s many duties, rather than simply going through the motions of completing tasks without regard to their actual effect.' },
    { section: SP3, topic: SP3, stem: 'A social development officer notices that a nearby officer in nutrition or health outreach appears to need coordination support for a joint community activity. What best reflects "teamwork skills," one of the listed competencies?', options: ['Avoiding any involvement in another officer’s area of work', 'Proactively coordinating and supporting the joint effort where it benefits the community and falls within the role’s scope', 'Taking over the other officer’s duties entirely without discussion', 'Reporting the other officer for needing help'], correct: 1, explanation: 'Teamwork in this context means proactively coordinating with colleagues across related duties (such as health or nutrition outreach) where it serves the community, not working in isolation or overstepping into another’s role.' },
    { section: SP4, topic: SP4, stem: 'A Cell has 420 households, of which 84 are registered VUP beneficiaries. What percentage of households are VUP beneficiaries?', options: ['15%', '18%', '20%', '24%'], correct: 2, explanation: '84 ÷ 420 = 0.20, or 20%.' },
    { section: SP4, topic: SP4, stem: 'A social development officer must visit 60 households over 12 working days at a constant rate. How many households should be visited per day?', options: ['4', '5', '6', '8'], correct: 1, explanation: '60 ÷ 12 = 5.' },
    { section: SP4, topic: SP4, stem: 'Out of 150 VUP beneficiary households reviewed, 24 were found to no longer meet the eligibility criteria. What percentage no longer qualify?', options: ['12%', '16%', '18%', '20%'], correct: 1, explanation: '24 ÷ 150 = 0.16, or 16%.' },
    { section: SP4, topic: SP4, stem: 'A Cell’s number of households receiving direct support fell from 90 to 72 over one year as households graduated. What is the percentage decrease?', options: ['15%', '18%', '20%', '25%'], correct: 2, explanation: '(90 − 72) ÷ 90 = 18 ÷ 90 = 0.20, or 20%.' },
    { section: SP4, topic: SP4, stem: 'A Sector has 8 Cells. If VUP households are distributed roughly equally and the Sector has a total of 960 VUP households, about how many does each Cell have?', options: ['100', '110', '120', '130'], correct: 2, explanation: '960 ÷ 8 = 120.' },
    { section: SP4, topic: SP4, stem: 'A household’s registered monthly income rose from RWF 18,000 to RWF 27,000. What is the percentage increase?', options: ['30%', '40%', '50%', '60%'], correct: 2, explanation: '(27,000 − 18,000) ÷ 18,000 = 9,000 ÷ 18,000 = 0.50, or 50%.' },
    { section: SP4, topic: SP4, stem: 'A data-verification sample of 40 household records found 6 with outdated information. If this error rate holds across a Cell’s 500 total records, how many would be expected to be outdated?', options: ['60', '65', '70', '75'], correct: 3, explanation: 'Error rate = 6 ÷ 40 = 15%. 15% × 500 = 75.' },
    { section: SP4, topic: SP4, stem: 'A community register listed 320 households. After a verification exercise, 28 households were removed as duplicates or no longer resident. How many households remain?', options: ['282', '290', '292', '298'], correct: 2, explanation: '320 − 28 = 292.' },
    { section: SP4, topic: SP4, stem: 'Three Cells reported 45, 38 and 52 pending beneficiary applications respectively. What is the total, and the average per Cell?', options: ['Total 135, average 42', 'Total 135, average 45', 'Total 145, average 45', 'Total 145, average 48'], correct: 1, explanation: '45 + 38 + 52 = 135. Average = 135 ÷ 3 = 45.' },
    { section: SP4, topic: SP4, stem: 'A report’s household count rose by 15% from last quarter’s figure of 240. What is the new count?', options: ['252', '264', '276', '280'], correct: 2, explanation: '240 × 1.15 = 276.' },
    { section: SP4, topic: SP4, stem: 'If a Cell processes beneficiary reassessments at a rate of 10 households per day, how many working days are needed to reassess 230 households?', options: ['20', '21', '22', '23'], correct: 3, explanation: '230 ÷ 10 = 23.' },
    { section: SP4, topic: SP4, stem: 'A household’s Ubudehe category changed, and its monthly support dropped from RWF 12,000 to RWF 7,200. What is the percentage decrease?', options: ['30%', '35%', '40%', '45%'], correct: 2, explanation: '(12,000 − 7,200) ÷ 12,000 = 4,800 ÷ 12,000 = 0.40, or 40%.' },
    { section: SP4, topic: SP4, stem: 'A table shows four Cells’ beneficiary counts: 60, 72, 55, 81. Which Cell has the highest count, and what is the combined total of all four?', options: ['Cell with 81; total 258', 'Cell with 81; total 268', 'Cell with 72; total 268', 'Cell with 81; total 278'], correct: 1, explanation: '60 + 72 + 55 + 81 = 268. The highest individual count is 81.' },
    { section: SP4, topic: SP4, stem: 'A household register is updated every quarter. If the last update was 7 months ago, roughly how many update cycles have been missed?', options: ['1', '2', '3', '4'], correct: 1, explanation: 'Quarterly updates occur roughly every 3 months; 7 months corresponds to about 2 missed cycles (6 months would be exactly 2; 7 months is just past that).' },
    { section: SP4, topic: SP4, stem: 'A Cell’s eligible-but-unregistered households were found to be 18, out of 234 total households. What percentage of all households are eligible but not yet registered?', options: ['About 6.7%', 'About 7.7%', 'About 8.7%', 'About 9.7%'], correct: 1, explanation: '18 ÷ 234 ≈ 0.0769, or about 7.7%.' },
    { section: SP4, topic: SP4, stem: 'Monthly household visits rose steadily: 40, 46, 52, 58 over four months, increasing by a constant amount. If the trend continues, what is the projected figure for month five?', options: ['60', '62', '64', '66'], correct: 2, explanation: 'The increase is 6 per month: 58 + 6 = 64.' },
    { section: SP4, topic: SP4, stem: 'A Cell’s budget for a community programme is RWF 2,400,000, to be spent evenly across 6 planned activities. How much is allocated per activity?', options: ['RWF 350,000', 'RWF 400,000', 'RWF 450,000', 'RWF 500,000'], correct: 1, explanation: '2,400,000 ÷ 6 = 400,000.' },
    { section: SP4, topic: SP4, stem: 'Of 180 households surveyed, 45 reported a family member had recently gained stable employment. What fraction and percentage does this represent?', options: ['1/4, 25%', '1/5, 20%', '1/3, 33%', '2/5, 40%'], correct: 0, explanation: '45 ÷ 180 = 0.25 = 1/4 = 25%.' },
    { section: SP4, topic: SP4, stem: 'A report comparing two quarters shows beneficiary numbers of 310 and 279. What is the percentage decrease from the first to the second quarter?', options: ['8%', '10%', '12%', '15%'], correct: 1, explanation: '(310 − 279) ÷ 310 = 31 ÷ 310 = 0.10, or 10%.' },
    { section: SP4, topic: SP4, stem: 'A social development officer splits 100 pending case files between two colleagues in a ratio of 3:2. How many files does each receive?', options: ['50 and 50', '55 and 45', '60 and 40', '65 and 35'], correct: 2, explanation: '3 + 2 = 5 parts; 100 ÷ 5 = 20 per part. 3 × 20 = 60 and 2 × 20 = 40.' },
    { section: SP4, topic: SP4, stem: 'A Cell’s beneficiary list grew from 150 to 195 over one year. What is the percentage growth?', options: ['25%', '30%', '35%', '40%'], correct: 1, explanation: '(195 − 150) ÷ 150 = 45 ÷ 150 = 0.30, or 30%.' },
    { section: SP4, topic: SP4, stem: 'An officer completes 18 household assessments on Monday, 22 on Tuesday, and 15 on Wednesday. What is the average number of assessments per day across these three days?', options: ['17', '18', '19', '20'], correct: 1, explanation: '(18 + 22 + 15) ÷ 3 = 55 ÷ 3 ≈ 18.3, which rounds to 18.' },
    { section: SP4, topic: SP4, stem: 'A District has 12 Sectors, each with an average of 6 Cells. Approximately how many Cells does the District have in total?', options: ['60', '66', '72', '78'], correct: 2, explanation: '12 × 6 = 72.' },
    { section: SP4, topic: SP4, stem: 'A programme’s community-mobilisation sessions reached 85 people in the first session and grew by 20% in the second session. About how many people attended the second session?', options: ['95', '100', '102', '105'], correct: 2, explanation: '85 × 1.20 = 102.' },
    { section: SP4, topic: SP4, stem: 'If 3 out of every 8 households surveyed report a child under 5 in the home, and the Cell has 400 households, about how many households would be expected to have a child under 5?', options: ['130', '140', '150', '160'], correct: 2, explanation: '3/8 × 400 = 150.' },
    { section: SP4, topic: SP4, stem: 'A report is due in 15 days, and 60 household files still need review at a sustainable pace of 5 per day. Will the deadline be met, and with how many spare days if so?', options: ['No, it will be 3 days late', 'Yes, with 3 spare days', 'Yes, with exactly 0 spare days', 'Yes, with 5 spare days'], correct: 1, explanation: '60 ÷ 5 = 12 days needed; 15 − 12 = 3 spare days.' },
    { section: SP4, topic: SP4, stem: 'A Cell’s register shows 210 households, of which 35 are headed by a single parent. What fraction of households are single-parent-headed?', options: ['1/8', '1/7', '1/6', '1/5'], correct: 2, explanation: '35 ÷ 210 = 1/6.' },
    { section: SP4, topic: SP4, stem: 'A social development officer’s weekly field-visit target is 25 households. Over 4 weeks, they completed 22, 28, 20, and 26. Did they meet their overall 4-week target of 100, and by how much?', options: ['No, 4 short', 'Yes, exactly on target', 'Yes, 4 over', 'No, 6 short'], correct: 0, explanation: '22 + 28 + 20 + 26 = 96, which is 4 short of the 100 target.' },
    { section: SP4, topic: SP4, stem: 'A community meeting had 140 attendees, of whom 56 were women. What percentage of attendees were women?', options: ['35%', '38%', '40%', '42%'], correct: 2, explanation: '56 ÷ 140 = 0.40, or 40%.' },
    { section: SP4, topic: SP4, stem: 'A Cell plans to visit all 180 of its registered beneficiary households exactly once over a 30-day period. On average, how many households must be visited per day to stay on schedule?', options: ['4', '5', '6', '7'], correct: 2, explanation: '180 ÷ 30 = 6.' },
    { section: SP4, topic: SP4, stem: 'A Sector’s total beneficiary count across its 6 Cells is 432, distributed roughly equally. About how many beneficiaries does each Cell have on average?', options: ['64', '68', '72', '76'], correct: 2, explanation: '432 ÷ 6 = 72.' },
  ],
};

// ───────────────────────────── Mock 2: Education, ECD & school feeding monitoring

const ED1 = 'Education access and performance indicators';
const ED2 = 'Early Childhood Development and school feeding';
const ED3 = 'Data collection, reporting and information management';
const ED4 = 'Community mobilisation on education and literacy';

export const hcsdMock2: TestDef = {
  country: 'RW',
  jobDeadlineAt: DEADLINE,
  category: 'government-administration',
  profession: PROFESSION,
  authority: 'MINALOC',
  slug: 'human-capital-social-development-officer-mock-exam-2',
  title: 'Human Capital & Social Development Officer — Mock Exam 2',
  summary: 'Practice monitoring education performance indicators, Early Childhood Development and school feeding, data reporting through information management systems, and community mobilisation on education and adult literacy.',
  free: false,
  difficulty: 'STANDARD',
  minutes: 120,
  sections: [{ name: ED1 }, { name: ED2 }, { name: ED3 }, { name: ED4 }],
  questions: [
    { section: ED1, topic: ED1, stem: 'Which of these is explicitly listed among the education indicators this role is expected to monitor at Cell level?', options: ['National exam board membership', 'Dropout, enrolment, attendance, teen-mother rates and parental participation in school activities', 'University tuition fee levels', 'Teacher salary scales'], correct: 1, explanation: 'The role’s duties specifically mention monitoring interventions related to education performance on indicators such as dropout, enrolment, attendance, teen mothers and participation of parents in school activities.' },
    { section: ED1, topic: ED1, stem: 'Why is monitoring "teen mothers" as an education indicator relevant to this role’s duties?', options: ['It has no relevance to education monitoring', 'Teenage pregnancy is a known factor affecting school dropout and continuation, so tracking it helps identify girls needing support to stay in or return to school', 'It is only relevant to health officers, not social development officers', 'It is tracked only for national statistics with no local action expected'], correct: 1, explanation: 'Teenage pregnancy is a recognised driver of school dropout; monitoring this indicator helps identify girls who may need support to continue or return to their education, directly supporting the role’s duties.' },
    { section: ED1, topic: ED1, stem: 'A Cell’s primary-school attendance rate has fallen noticeably over one term. What is an appropriate first step for the social development officer?', options: ['Ignore the drop since it is a school matter only', 'Investigate likely causes (e.g. economic hardship, distance, health issues) in coordination with the school and relevant local structures, and report findings', 'Report the figure with no further action or investigation', 'Close the school'], correct: 1, explanation: 'Monitoring duties include understanding the causes behind changes in indicators like attendance, coordinating with schools and relevant structures, and reporting findings so appropriate action can follow.' },
    { section: ED1, topic: ED1, stem: 'What does "parental participation in school activities" as a monitored indicator most likely capture?', options: ['Whether parents pay school fees on time only', 'The degree to which parents/guardians are engaged with their children’s education, such as attending meetings or supporting learning at home', 'Whether parents are themselves literate', 'Whether parents live in the same Cell as the school'], correct: 1, explanation: 'This indicator generally captures how engaged parents or guardians are with their children’s schooling, since parental engagement is widely linked to better educational outcomes.' },
    { section: ED1, topic: ED1, stem: 'Why might a social development officer’s monitoring role on education differ from a teacher’s or headteacher’s role?', options: ['There is no meaningful difference', 'The officer typically monitors community-level and household-level factors affecting education access and participation, complementing (not replacing) the school’s own instructional and administrative role', 'The officer sets the national curriculum', 'The officer is responsible for teacher recruitment'], correct: 1, explanation: 'The social development officer’s role focuses on community and household-level factors affecting access and participation (such as dropout causes, parental engagement), working alongside — not replacing — the school’s instructional and administrative functions.' },
    { section: ED1, topic: ED1, stem: 'A Cell has 3 primary schools with enrolment of 420, 350 and 380 pupils. What is the Cell’s total primary enrolment?', options: ['1,100', '1,130', '1,150', '1,180'], correct: 2, explanation: '420 + 350 + 380 = 1,150.' },
    { section: ED1, topic: ED1, stem: 'If 24 pupils out of 480 enrolled are recorded as having dropped out this term, what is the dropout rate?', options: ['3%', '4%', '5%', '6%'], correct: 2, explanation: '24 ÷ 480 = 0.05, or 5%.' },
    { section: ED1, topic: ED1, stem: 'Why is tracking dropout alongside enrolment more informative than tracking enrolment alone?', options: ['It is not more informative', 'Enrolment alone does not show whether pupils stay in school; tracking dropout reveals whether gains in initial enrolment are actually being sustained', 'Dropout and enrolment measure exactly the same thing', 'Only enrolment matters for planning purposes'], correct: 1, explanation: 'High initial enrolment can mask a problem if many pupils later drop out; tracking both together gives a fuller, more accurate picture of whether children are actually completing their education.' },
    { section: ED1, topic: ED1, stem: 'A school reports 92% attendance for the term, up from 85% the previous term. What is the percentage-point increase?', options: ['5', '6', '7', '8'], correct: 2, explanation: '92 − 85 = 7 percentage points.' },
    { section: ED1, topic: ED1, stem: 'What is a reasonable, non-judgemental first response if household economic hardship is identified as a likely cause of a child’s irregular school attendance?', options: ['Blame the parents publicly', 'Explore whether the household might be eligible for relevant social-protection or school-support programmes, and refer them appropriately', 'Report the child to the police', 'Do nothing, since economic hardship is outside the role’s scope'], correct: 1, explanation: 'Since this role bridges social protection and education monitoring, a reasonable response to hardship-driven attendance problems is to explore relevant support programmes and make an appropriate referral.' },
    { section: ED1, topic: ED1, stem: 'A table shows four schools’ dropout counts this term: 5, 8, 3, 6 (out of total enrolments of 200, 240, 150, 210 respectively). Which school has the highest dropout rate?', options: ['School with 5 dropouts (200 enrolled)', 'School with 8 dropouts (240 enrolled)', 'School with 3 dropouts (150 enrolled)', 'School with 6 dropouts (210 enrolled)'], correct: 1, explanation: 'Rates: 5/200=2.5%, 8/240≈3.33%, 3/150=2%, 6/210≈2.86%. The school with 8 dropouts out of 240 has the highest rate at about 3.33%.' },
    { section: ED1, topic: ED1, stem: 'Why should an officer be cautious about drawing conclusions from a single term’s attendance data alone?', options: ['A single term’s data is always sufficient and final', 'Short-term fluctuations can result from temporary factors (e.g. one bad harvest season), so trends over multiple terms give a more reliable picture', 'Attendance data is never useful regardless of timeframe', 'Only annual data is ever collected, so this concern does not apply'], correct: 1, explanation: 'A single term can be affected by temporary, one-off factors; looking at trends across multiple terms gives a more reliable basis for understanding real, persistent issues versus short-term fluctuations.' },
    { section: ED1, topic: ED1, stem: 'A Cell’s adult literacy programme enrolled 60 participants, of whom 45 completed the full course. What is the completion rate?', options: ['65%', '70%', '75%', '80%'], correct: 2, explanation: '45 ÷ 60 = 0.75, or 75%.' },
    { section: ED1, topic: ED1, stem: 'What does "adult literacy," listed among this role’s education-related duties, generally aim to address?', options: ['Only children’s reading skills', 'Helping adults who did not complete basic education gain literacy and numeracy skills, supporting broader human-capital development', 'University-level continuing education only', 'Teacher training exclusively'], correct: 1, explanation: 'Adult literacy programmes target adults who lack basic literacy/numeracy skills, supporting their participation in economic and civic life and contributing to broader human-capital development goals.' },
    { section: ED1, topic: ED1, stem: 'Why would monitoring "performance" (not just enrolment) matter for education-related duties, even though the officer is not a teacher?', options: ['Performance has no relevance to a non-teaching role', 'Weak performance alongside other indicators (attendance, dropout) can reveal underlying household or community issues the officer may be positioned to help address', 'Only teachers are ever expected to notice performance issues', 'Performance monitoring duplicates what schools already do, with no added value'], correct: 1, explanation: 'While not responsible for instruction itself, an officer who sees performance issues alongside attendance or dropout patterns may identify underlying household/community factors that fall within their own mandate to address or refer onward.' },
    { section: ED1, topic: ED1, stem: 'An officer is reviewing school-related data for the Cell’s quarterly report. Which combination of indicators would give the clearest overall picture of education access and continuation?', options: ['Enrolment numbers alone', 'Enrolment, attendance and dropout together, viewed over more than one term', 'Only the number of teachers at each school', 'The size of each school’s building'], correct: 1, explanation: 'Looking at enrolment, attendance and dropout together, and over more than one term, gives a much fuller and more reliable picture of education access and continuation than any single indicator alone.' },
    { section: ED1, topic: ED1, stem: 'A Cell has 520 school-age children, of whom 494 are currently enrolled. What percentage are NOT enrolled?', options: ['4%', '5%', '6%', '7%'], correct: 1, explanation: '(520 − 494) ÷ 520 = 26 ÷ 520 = 0.05, or 5%.' },
    { section: ED1, topic: ED1, stem: 'Why might an officer coordinate with health staff when investigating a rise in school absenteeism?', options: ['Health and education are entirely unrelated areas', 'Illness or health-related issues (e.g. unaddressed health conditions, outbreaks) can be a significant cause of absenteeism, so cross-sector coordination helps identify the real cause', 'Health staff have no information relevant to school attendance', 'Coordination across sectors is prohibited by policy'], correct: 1, explanation: 'Health issues are a recognised cause of absenteeism, so coordinating with health staff can help identify whether health-related factors, rather than purely economic or social ones, are driving a rise in absences.' },
    { section: ED1, topic: ED1, stem: 'What is the most appropriate way to use education indicator data at Cell level once collected?', options: ['File it away with no further use', 'Analyse it to identify patterns or problems, report findings upward, and use it to inform local action such as referrals or mobilisation', 'Delete it after one term to save storage', 'Share it publicly with no analysis or context'], correct: 1, explanation: 'Collected data should be analysed, reported appropriately, and used to inform concrete local action — not simply filed away or shared without context or follow-up.' },
    { section: ED1, topic: ED1, stem: 'A Sector compares dropout rates across its Cells: 3%, 7%, 4%, 8%, 5%, 6%. What is the average dropout rate across these six Cells?', options: ['5%', '5.5%', '6%', '6.5%'], correct: 1, explanation: '(3+7+4+8+5+6) ÷ 6 = 33 ÷ 6 = 5.5%.' },
    { section: ED2, topic: ED2, stem: 'What is the National Early Childhood Development Programme (NECDP) in Rwanda generally concerned with?', options: ['University admissions policy', 'Supporting the development, care and early learning of young children before primary school age, as part of national education and health strategy', 'Teacher pension schemes', 'Secondary-school curriculum design'], correct: 1, explanation: 'Rwanda’s National Early Childhood Development Programme is named among the country’s strategies for supporting young children’s early development, care and learning before they reach primary-school age.' },
    { section: ED2, topic: ED2, stem: 'Why does Early Childhood Development (ECD) fall within the scope of a "human capital" role, rather than being treated as purely a childcare matter?', options: ['ECD is unrelated to human capital', 'Strong early development (cognitive, physical, social) in young children builds the foundation for later learning and productivity, making it a core human-capital investment', 'Only secondary education counts as human capital', 'ECD has no measurable long-term effects'], correct: 1, explanation: 'Early childhood is a critical period for cognitive, physical and social development; investing in it is widely recognised as foundational to later learning and productivity, making ECD a core part of human-capital development.' },
    { section: ED2, topic: ED2, stem: 'Rwanda’s National Comprehensive School Feeding Policy was issued by which ministry?', options: ['Ministry of Health', 'Ministry of Education', 'Ministry of Local Government', 'Ministry of Finance and Economic Planning'], correct: 1, explanation: 'Rwanda’s National Comprehensive School Feeding Policy (issued in November 2019) was issued by the Ministry of Education, setting out how the school feeding programme is coordinated and run.' },
    { section: ED2, topic: ED2, stem: 'What is one of the stated goals of Rwanda’s school feeding programme, beyond simply providing food?', options: ['Replacing the need for schools entirely', 'Supporting human-capital creation by addressing malnutrition/hunger and encouraging continued school attendance', 'Reducing the number of children enrolled in school', 'Eliminating the need for any health programmes'], correct: 1, explanation: 'School feeding is intended to address malnutrition and hunger while supporting human-capital creation and giving children a positive incentive to attend school regularly.' },
    { section: ED2, topic: ED2, stem: 'Why might school feeding and ECD programmes be linked in practice (e.g. shared supply chains reaching both schools and ECD centres)?', options: ['They are never linked in practice', 'Both target young children’s nutrition and development, so coordinating resources (such as food supply) across schools and ECD centres can improve efficiency and reach', 'ECD centres never serve any food to children', 'Linking the two is prohibited by policy'], correct: 1, explanation: 'Since both school feeding and ECD programmes aim to support young children’s nutrition and development, coordinating resources such as food supply across schools and ECD centres can improve efficiency and overall reach.' },
    { section: ED2, topic: ED2, stem: 'A Cell’s ECD centre reports irregular attendance among 3-5 year olds. What is a reasonable first step for the social development officer?', options: ['Close the ECD centre', 'Investigate likely causes (distance, household circumstances, awareness) and consider community mobilisation to encourage attendance', 'Ignore it since ECD is not part of the role’s scope', 'Transfer all children to primary school immediately regardless of age'], correct: 1, explanation: 'Given the role’s duty to monitor and support ECD interventions, investigating causes of irregular attendance and considering community mobilisation is a reasonable, proportionate first step.' },
    { section: ED2, topic: ED2, stem: 'Which of these would most directly support better nutrition outcomes for young children at Cell level, consistent with this role’s duties?', options: ['Ignoring nutrition entirely since it is a health-sector matter only', 'Monitoring and supporting interventions to prevent and reduce malnutrition and stunting, and coordinating with relevant programmes such as school feeding', 'Only monitoring nutrition for children over age 10', 'Treating nutrition as unrelated to education or social development'], correct: 1, explanation: 'The role explicitly includes monitoring interventions to prevent and reduce malnutrition and stunting, which connects directly to nutrition-related programmes such as school feeding and ECD support.' },
    { section: ED2, topic: ED2, stem: 'An ECD centre serves 85 children, of whom 68 attend regularly (at least 4 days a week). What percentage attend regularly?', options: ['75%', '78%', '80%', '82%'], correct: 2, explanation: '68 ÷ 85 = 0.80, or 80%.' },
    { section: ED2, topic: ED2, stem: 'A school feeding programme serves 3 meals’ worth of ingredients per child per week across 240 enrolled children. How many total weekly meal-portions does this represent?', options: ['600', '660', '700', '720'], correct: 3, explanation: '240 × 3 = 720.' },
    { section: ED2, topic: ED2, stem: 'Why would a social development officer need to coordinate with both education and health actors on school feeding, rather than treating it as purely an education matter?', options: ['Health has no connection to school feeding', 'School feeding affects both nutrition/health outcomes and educational attendance/performance, so effective monitoring benefits from coordination across both sectors', 'Coordination across sectors is never useful', 'School feeding is managed entirely outside government, with no local coordination needed'], correct: 1, explanation: 'Because school feeding touches both nutritional/health outcomes and educational participation, coordinating across education and health actors supports more effective monitoring and problem-solving.' },
    { section: ED2, topic: ED2, stem: 'What is a sensible interpretation of "supporting the implementation of ECD interventions" as a monitoring duty, rather than a hands-on caregiving duty?', options: ['Personally providing childcare at the ECD centre full-time', 'Tracking whether planned ECD interventions are being carried out, identifying gaps, and helping coordinate support or escalate issues', 'Replacing ECD caregivers with the officer’s own judgement on child development', 'Ignoring ECD entirely since it is not a core duty'], correct: 1, explanation: 'This duty is about monitoring and supporting implementation — tracking progress, identifying gaps and coordinating or escalating issues — not personally delivering hands-on childcare, which is the caregivers’ role.' },
    { section: ED2, topic: ED2, stem: 'A household with a child showing signs of poor nutrition is identified during a routine visit. What combination of this role’s duties is most relevant to respond appropriately?', options: ['None — nutrition is entirely outside this role', 'Flagging the case for appropriate health/nutrition follow-up, and considering whether the household may need social-protection support as well', 'Publicly announcing the family’s situation in the community', 'Removing the child from the household immediately without referral to any service'], correct: 1, explanation: 'An appropriate, duty-consistent response combines flagging the case for health/nutrition follow-up with considering whether broader social-protection support could help address underlying household circumstances.' },
    { section: ED2, topic: ED2, stem: 'An ECD centre’s enrolment grew from 60 to 78 children over one year. What is the percentage growth?', options: ['25%', '28%', '30%', '32%'], correct: 2, explanation: '(78 − 60) ÷ 60 = 18 ÷ 60 = 0.30, or 30%.' },
    { section: ED2, topic: ED2, stem: 'Why is early identification of malnutrition in young children particularly important, compared with addressing it later in childhood?', options: ['Timing makes no difference to outcomes', 'Early childhood is a critical window for physical and cognitive development, so malnutrition at this stage can have longer-lasting effects if not addressed promptly', 'Malnutrition only matters after age 10', 'Early identification is harder than late identification, so it should be avoided'], correct: 1, explanation: 'Because early childhood is a critical developmental window, malnutrition during this period can have more lasting effects on physical and cognitive development if not identified and addressed promptly.' },
    { section: ED2, topic: ED2, stem: 'A Cell has 4 ECD centres with enrolments of 45, 60, 38 and 52. What is the total ECD enrolment, and the average per centre?', options: ['Total 185, average about 46', 'Total 195, average about 49', 'Total 195, average about 46', 'Total 205, average about 51'], correct: 1, explanation: '45 + 60 + 38 + 52 = 195. Average = 195 ÷ 4 = 48.75, which rounds to about 49.' },
    { section: ED2, topic: ED2, stem: 'What role does community mobilisation typically play in supporting ECD and school feeding programmes?', options: ['No role at all', 'Raising awareness among households of the programmes’ availability and benefits, and encouraging participation (e.g. regular attendance, contribution where applicable)', 'Mobilisation is only relevant to political campaigns, not social programmes', 'Community mobilisation replaces the need for the programmes themselves'], correct: 1, explanation: 'Community mobilisation helps raise awareness of available programmes and their benefits, encouraging participation such as regular ECD or school attendance, which supports the programmes’ overall effectiveness.' },
    { section: ED2, topic: ED2, stem: 'Why should an officer track school feeding and ECD indicators over time rather than relying on a single snapshot?', options: ['A single snapshot is always sufficient', 'Trends over time reveal whether interventions are working and help identify emerging problems early, rather than only confirming a one-off status', 'Tracking over time is prohibited by policy', 'Only annual national statistics are ever useful for this purpose'], correct: 1, explanation: 'Tracking trends over time, rather than relying on a single snapshot, helps reveal whether interventions are genuinely working and allows emerging problems to be identified and addressed earlier.' },
    { section: ED2, topic: ED2, stem: 'A school feeding programme budget of RWF 1,800,000 per term is spent evenly across 90 school days. What is the average daily spend?', options: ['RWF 18,000', 'RWF 20,000', 'RWF 22,000', 'RWF 24,000'], correct: 1, explanation: '1,800,000 ÷ 90 = 20,000.' },
    { section: ED2, topic: ED2, stem: 'Which best reflects the social development officer’s appropriate scope of involvement in school feeding and ECD, consistent with the duties listed on the posting?', options: ['Designing the national school feeding policy', 'Monitoring implementation at Cell level, identifying problems, supporting coordination, and reporting — not setting national policy or personally running the programmes', 'Having no involvement at all', 'Taking over the headteacher’s administrative duties'], correct: 1, explanation: 'The role’s duties are about monitoring, supporting coordination and reporting at Cell level — not setting national policy (a ministry-level function) or taking over duties that belong to schools or ECD centres themselves.' },
    { section: ED2, topic: ED2, stem: 'An ECD centre reduces its no-show rate from 22% to 14% after a community awareness campaign. What is the percentage-point improvement?', options: ['6', '7', '8', '9'], correct: 2, explanation: '22 − 14 = 8 percentage points.' },
    { section: ED3, topic: ED3, stem: 'What is the main purpose of "reporting using appropriate reporting mechanisms and information management systems," a duty explicitly listed for this role?', options: ['To create unnecessary paperwork', 'To ensure accurate, timely information reaches Sector, District and national levels through the proper channels, supporting informed decision-making', 'To replace the need for any field visits', 'Reporting is optional and rarely expected'], correct: 1, explanation: 'Structured reporting through the appropriate systems ensures that accurate, timely information flows to higher levels of administration, supporting decisions that rely on reliable Cell-level data.' },
    { section: ED3, topic: ED3, stem: 'Why is data consolidation (combining data from multiple social, health and education sources) an important part of this role?', options: ['It serves no real purpose', 'It creates a more complete, accurate picture of a Cell’s overall situation than any single data source alone could provide, supporting better-informed action and reporting', 'Consolidation is only relevant to statisticians at the national level', 'Data from different sectors should never be combined'], correct: 1, explanation: 'Combining data across social, health and education sources gives a fuller picture of circumstances at Cell level than any single source alone, supporting more accurate reporting and better-informed decisions.' },
    { section: ED3, topic: ED3, stem: 'An officer discovers an error in previously submitted Cell-level data. What is the appropriate response?', options: ['Ignore it since the report was already submitted', 'Correct the error and communicate the correction through the proper channel as soon as practical, so decisions based on it are not misled', 'Blame a colleague for the error without investigation', 'Submit a new report with no mention of the correction'], correct: 1, explanation: 'Correcting the error and communicating it through the proper channel protects the integrity of data-based decisions, consistent with accountability and accurate reporting duties.' },
    { section: ED3, topic: ED3, stem: 'What is "digital literacy," one of the required competencies, most directly used for in this role’s day-to-day work?', options: ['Entirely unrelated to the role’s core duties', 'Using information management systems to record, consolidate and report data as part of routine monitoring duties', 'Only needed for occasional personal use outside of work', 'Digital literacy is required only for senior management positions'], correct: 1, explanation: 'Given the role’s emphasis on data collection, consolidation and reporting through information management systems, digital literacy is directly relevant to carrying out these core duties.' },
    { section: ED3, topic: ED3, stem: 'Why might inconsistent data formats across different Cells create a problem at Sector or District level?', options: ['Inconsistent formats never cause problems', 'They can make it difficult to accurately combine, compare or analyse data across Cells, undermining Sector- or District-level reporting and planning', 'Formats are always automatically standardised with no effort required', 'Data formatting has no bearing on reporting quality'], correct: 1, explanation: 'If different Cells record or submit data in inconsistent formats, it becomes harder to accurately combine and compare information at Sector or District level, which can undermine the quality of higher-level reporting and planning.' },
    { section: ED3, topic: ED3, stem: 'A new information management system is introduced for reporting. What is the most appropriate initial response for an officer, consistent with "commitment to continuous learning"?', options: ['Refuse to use it and continue with the old method indefinitely', 'Learn the new system and adapt reporting practices accordingly, seeking support if needed', 'Ignore the new system until forced to use it', 'Assume the new system requires no learning at all'], correct: 1, explanation: 'Continuous learning as a competency means proactively learning new tools or systems introduced for the role, such as an updated reporting system, rather than resisting change or ignoring it.' },
    { section: ED3, topic: ED3, stem: 'Why should raw field data (such as handwritten household notes) typically be converted into a structured digital or standard format before being used in formal reporting?', options: ['Raw notes are always preferable and should never be converted', 'A structured format supports accuracy, consistency and easier aggregation/analysis at higher levels, reducing the risk of misinterpretation', 'Conversion is purely cosmetic and has no practical benefit', 'Formal reporting never uses field-collected data'], correct: 1, explanation: 'Converting raw field data into a structured format improves accuracy and consistency and makes it easier to aggregate and analyse at Sector or District level, reducing the risk that information is lost or misread along the way.' },
    { section: ED3, topic: ED3, stem: 'A report is due weekly, but an officer finds that collecting all the needed data by the deadline is difficult under the current workload. What is the most appropriate response, reflecting both professionalism and realistic time management?', options: ['Submit fabricated data to meet the deadline', 'Communicate the challenge to the supervisor, propose a realistic plan, and submit the most accurate data available while flagging any gaps honestly', 'Simply miss the deadline with no communication', 'Stop reporting altogether'], correct: 1, explanation: 'Honest communication about a genuine challenge, paired with a realistic plan and transparent flagging of any data gaps, reflects professionalism and sound time management far better than fabrication or silent non-compliance.' },
    { section: ED3, topic: ED3, stem: 'What is a key risk of relying solely on memory or informal notes for Cell-level reporting, rather than systematic record-keeping?', options: ['There is no risk; memory is always reliable', 'Information can be forgotten, distorted or lost, undermining the accuracy and continuity of records, especially if staff changes occur', 'Systematic record-keeping is always slower and therefore worse', 'Memory-based reporting is the official standard required by policy'], correct: 1, explanation: 'Relying on memory or informal notes risks losing or distorting information over time, and creates continuity problems if staff change — systematic, documented record-keeping protects against both risks.' },
    { section: ED3, topic: ED3, stem: 'An officer collects data from 6 villages in the Cell for a report. If each village takes about 45 minutes to process, how long will data processing take in total?', options: ['3.5 hours', '4 hours', '4.5 hours', '5 hours'], correct: 2, explanation: '6 × 45 minutes = 270 minutes = 4.5 hours.' },
    { section: ED3, topic: ED3, stem: 'Why is it good practice to keep a clear audit trail (dates, sources, who recorded what) for Cell-level data?', options: ['An audit trail serves no real purpose', 'It supports accountability and makes it possible to verify, correct or explain data later if questions arise', 'Audit trails are only required for financial data, never social data', 'Keeping an audit trail is prohibited to save time'], correct: 1, explanation: 'A clear audit trail supports accountability and allows data to be verified, corrected or explained later, which is especially important when decisions at higher levels rely on that information.' },
    { section: ED3, topic: ED3, stem: 'A district requests historical data on VUP beneficiaries going back two years. Why is maintaining organised historical records valuable for this kind of request?', options: ['Historical records are never requested in practice', 'They allow the officer to respond accurately and efficiently to such requests, supporting transparency and informed decision-making at higher levels', 'Only current-year data is ever useful for any purpose', 'Organising historical records is explicitly discouraged by policy'], correct: 1, explanation: 'Well-organised historical records let an officer respond accurately and efficiently to requests like this, supporting transparency and giving higher levels of government a fuller basis for decisions.' },
    { section: ED3, topic: ED3, stem: 'Which best reflects good practice when a reporting template changes partway through the year?', options: ['Keep using the old template regardless of the change', 'Adopt the new template as instructed, ensure historical data can still be understood or mapped across the change, and clarify any uncertainty with the relevant supervisor', 'Stop reporting until the old template is restored', 'Mix the old and new templates inconsistently without clarification'], correct: 1, explanation: 'Good practice is to adopt the updated template, make sure historical data remains understandable across the transition, and seek clarification on anything unclear, rather than ignoring the change or mixing formats inconsistently.' },
    { section: ED3, topic: ED3, stem: 'Why might "attention and concentration" (one of the posting’s listed psychometric domains) be particularly relevant to the data and reporting aspects of this role?', options: ['These domains are irrelevant to data work', 'Careful, error-free data entry and review require sustained attention, especially given the volume and variety of data this role handles across many programme areas', 'Attention and concentration only matter for creative tasks, not administrative ones', 'Data work requires no real mental effort'], correct: 1, explanation: 'Given the volume and variety of data this role handles across social, health and education domains, sustained attention and concentration are directly relevant to accurate data entry, review and reporting.' },
    { section: ED3, topic: ED3, stem: 'A colleague suggests rounding all figures generously upward "to look better" in a report to the District. What is the correct response?', options: ['Agree, since it makes the Cell look more successful', 'Decline, and report figures accurately, since misleading data undermines trust and can lead to poor decisions based on inaccurate information', 'Round everything downward instead, for no reason', 'Ignore the suggestion without addressing it'], correct: 1, explanation: 'Accurate reporting is essential to the integrity of decision-making at higher levels; deliberately inflating or distorting figures, even with good intentions, undermines trust and can lead to poor decisions.' },
    { section: ED4, topic: ED4, stem: 'What is the main purpose of "community mobilisation campaigns" on education and literacy, as listed among this role’s duties?', options: ['To fulfil a bureaucratic requirement with no real goal', 'To raise awareness, build support and encourage participation among residents in education and literacy-related programmes and behaviours', 'To replace the need for any formal education system', 'To collect taxes from residents'], correct: 1, explanation: 'Community mobilisation campaigns aim to raise awareness and encourage participation in relevant programmes (such as education and adult literacy), building community support for improved outcomes.' },
    { section: ED4, topic: ED4, stem: 'A mobilisation campaign on the importance of girls’ education is planned for the Cell. Which approach would likely be most effective, consistent with "inclusiveness" and "communication and engagement with citizens"?', options: ['A one-way announcement with no opportunity for questions or discussion', 'Engaging directly with parents, local leaders and community members, listening to their concerns, and tailoring messages to address specific local barriers', 'Posting a single notice with no further engagement', 'Targeting only fathers, excluding mothers from the discussion'], correct: 1, explanation: 'Effective mobilisation typically involves genuine two-way engagement — listening to community concerns and tailoring messages to address specific local barriers — rather than one-way, exclusionary or minimal communication.' },
    { section: ED4, topic: ED4, stem: 'Why might involving local leaders (e.g. village or Cell leadership) in a literacy mobilisation campaign increase its effectiveness?', options: ['Local leaders have no influence on community behaviour', 'Local leaders often hold trust and influence within the community, which can help encourage participation and legitimise the campaign’s messages', 'Involving local leaders is prohibited by policy', 'Local leaders are only relevant to political matters, never social programmes'], correct: 1, explanation: 'Local leaders often have established trust and influence in their communities, which can help legitimise a campaign’s messages and encourage genuine participation from residents.' },
    { section: ED4, topic: ED4, stem: 'A literacy programme has low enrolment despite apparent community need. What would be a reasonable diagnostic step before launching another awareness campaign?', options: ['Assume residents simply do not care and give up', 'Investigate specific barriers (e.g. timing conflicts with work, distance, childcare needs, stigma) through direct conversations with the community', 'Cancel the programme immediately without investigation', 'Blame the previous campaign’s organisers with no further analysis'], correct: 1, explanation: 'Before repeating an awareness campaign, it is more effective to investigate specific, concrete barriers (such as timing, distance or childcare) through direct community conversations, which can reveal fixable practical obstacles.' },
    { section: ED4, topic: ED4, stem: 'A mobilisation session on education reaches 60 people out of an estimated 150 eligible household representatives in the target area. What is the participation rate?', options: ['35%', '40%', '45%', '50%'], correct: 1, explanation: '60 ÷ 150 = 0.40, or 40%.' },
    { section: ED4, topic: ED4, stem: 'Why is it important to measure the outcomes of a mobilisation campaign (e.g. changes in attendance or enrolment afterward), not just the number of attendees at the campaign event itself?', options: ['Attendance at the event is the only thing that ever matters', 'Attendance alone does not show whether the campaign actually changed behaviour or outcomes; tracking subsequent indicators shows whether the campaign was effective', 'Measuring outcomes afterward is never possible', 'Campaigns never have any measurable effect, so tracking is pointless'], correct: 1, explanation: 'Event attendance shows reach, but tracking subsequent indicators (such as enrolment or attendance changes) shows whether the campaign genuinely influenced behaviour — the real measure of effectiveness.' },
    { section: ED4, topic: ED4, stem: 'What is a reasonable way to sustain the impact of a one-time mobilisation campaign over time?', options: ['Assume a single campaign’s effect will last indefinitely with no further action', 'Follow up periodically, reinforce messages through ongoing community engagement, and monitor relevant indicators to see whether the change is holding', 'Never repeat or reinforce any messaging', 'Rely solely on posters with no interpersonal engagement'], correct: 1, explanation: 'Sustaining impact typically requires periodic follow-up and reinforcement through ongoing engagement, plus monitoring relevant indicators to check whether the initial change in behaviour is holding over time.' },
    { section: ED4, topic: ED4, stem: 'A mobilisation campaign budget of RWF 450,000 is to be spent across 3 planned community sessions. How much is available per session on average?', options: ['RWF 120,000', 'RWF 135,000', 'RWF 150,000', 'RWF 165,000'], correct: 2, explanation: '450,000 ÷ 3 = 150,000.' },
    { section: ED4, topic: ED4, stem: 'Why might combining education/literacy mobilisation with other community activities (e.g. a health outreach day) be a practical approach?', options: ['Combining activities is never practical', 'It can reach more residents efficiently by leveraging an occasion when the community is already gathered, rather than requiring a separate event for every topic', 'Mixing topics always confuses residents with no benefit', 'Only one topic may ever be discussed at any community gathering, by policy'], correct: 1, explanation: 'Combining complementary activities, such as pairing education/literacy messaging with a health outreach day, can efficiently reach more residents by using occasions when the community is already gathered.' },
    { section: ED4, topic: ED4, stem: 'A literacy class has places for 30 learners but 42 have expressed interest. What is a reasonable, equitable way to handle the shortfall?', options: ['Accept only the first 30 who registered on paper, with no further planning', 'Explore options such as adding a second class, prioritising based on clear need-based criteria, or creating a waiting list, while communicating transparently with applicants', 'Turn away the remaining 12 with no explanation or plan', 'Cancel the class entirely due to high demand'], correct: 1, explanation: 'A reasonable, equitable response explores practical options (a second class, clear need-based prioritisation, or a transparent waiting list) rather than an arbitrary cutoff or outright cancellation.' },
    { section: ED4, topic: ED4, stem: 'What best reflects "clear and effective communication" (a listed psychometric/competency domain) in the context of a mobilisation campaign?', options: ['Using complex technical language to sound authoritative', 'Conveying messages in a way the target audience can easily understand and act on, adapted to the community’s context and needs', 'Communicating as infrequently as possible', 'Avoiding any two-way interaction with the audience'], correct: 1, explanation: 'Clear and effective communication means conveying messages so the target audience can easily understand and act on them, adapted to their specific context — not using unnecessarily complex language or avoiding interaction.' },
    { section: ED3, topic: ED3, stem: 'A supervisor asks for the Cell’s latest school-feeding data "right now" but the officer’s records are only updated through last month. What is the best response?', options: ['Make up current-looking numbers to avoid seeming behind', 'Provide the most recent verified data available, clearly labelled with its date, and note that an update is in progress', 'Refuse to provide any data at all', 'Provide last year’s data without explanation'], correct: 1, explanation: 'Providing the most recent verified data, clearly dated, with a note that an update is underway, is honest and useful — fabricating current-looking numbers or withholding data entirely would both be worse responses.' },
    { section: ED3, topic: ED3, stem: 'Why is version control (knowing which copy of a dataset or report is the most current) important for Cell-level reporting?', options: ['Version control has no practical relevance', 'Using an outdated version could mean decisions are based on stale or superseded information, so knowing the current version avoids this risk', 'Only one version of any document is ever created, so this is a non-issue', 'Version control is solely an IT department concern'], correct: 1, explanation: 'Without clear version control, there is a real risk that outdated or superseded data gets used for a decision, so knowing which version is current is directly relevant to accurate reporting.' },
    { section: ED3, topic: ED3, stem: 'An officer notices that a colleague in a neighbouring Cell reports data in a format that does not match the standard template. What is an appropriate response?', options: ['Ignore it since it is not the officer’s concern', 'Raise the inconsistency with the colleague or the relevant supervisor so reporting can be standardised, supporting accurate Sector-level aggregation', 'Publicly criticise the colleague', 'Copy the non-standard format for the officer’s own reports too'], correct: 1, explanation: 'Raising inconsistencies constructively, through the colleague or a supervisor, supports standardised, accurate reporting that aggregates correctly at Sector level — rather than ignoring the issue or spreading the inconsistency further.' },
    { section: ED3, topic: ED3, stem: 'A Cell’s data shows a sudden, large jump in registered beneficiaries between two reporting periods with no clear explanation. What is the most responsible step before submitting the report?', options: ['Submit it as-is without checking', 'Investigate the cause of the jump (e.g. a genuine change, a data-entry error, or a backlog being cleared) before finalising and submitting the report', 'Round the number down arbitrarily to make it look less dramatic', 'Delete the anomalous figure without explanation'], correct: 1, explanation: 'An unexplained, large jump in the data warrants investigation before submission, to distinguish a genuine change from a data-entry error or other artefact — simply submitting, rounding or deleting the figure without checking risks reporting inaccurate information.' },
    { section: ED3, topic: ED3, stem: 'Why might maintaining both a digital and a brief physical/backup record be a sensible practice in some Cell-level settings?', options: ['Backups are never useful under any circumstances', 'It protects against data loss from technical issues (e.g. device failure, connectivity problems) that could otherwise disrupt reporting continuity', 'Physical records should always fully replace digital systems', 'Maintaining two records is prohibited by policy'], correct: 1, explanation: 'Keeping a backup — physical or digital — protects against data loss from technical issues such as device failure or connectivity problems, helping maintain continuity of records and reporting.' },
    { section: ED3, topic: ED3, stem: 'What is a reasonable approach when an officer is unsure how to categorise a particular case in a reporting system (e.g. an ambiguous household situation)?', options: ['Guess without asking anyone', 'Seek clarification from a supervisor or established guidance before finalising the categorisation, to ensure consistency with how similar cases are handled elsewhere', 'Leave the case uncategorised indefinitely with no follow-up', 'Invent a new category without approval'], correct: 1, explanation: 'Seeking clarification before finalising an ambiguous categorisation helps ensure consistency with how similar cases are handled elsewhere, supporting the overall reliability of aggregated data.' },
    { section: ED3, topic: ED3, stem: 'A report covering 8 different programme areas takes an officer 2 hours per area on average to compile. How long will the full report take?', options: ['14 hours', '16 hours', '18 hours', '20 hours'], correct: 1, explanation: '8 × 2 = 16 hours.' },
    { section: ED3, topic: ED3, stem: 'Why is it useful to clearly separate "verified" data from "preliminary/unverified" data when reporting?', options: ['There is no useful distinction between the two', 'It helps readers of the report understand the reliability of each figure, preventing preliminary estimates from being mistaken for confirmed facts', 'Verified and preliminary data are always identical, so labelling is unnecessary', 'Labelling data this way is prohibited'], correct: 1, explanation: 'Clearly labelling data as verified or preliminary helps readers correctly judge how much confidence to place in each figure, preventing early estimates from being mistaken for confirmed, final information.' },
    { section: ED3, topic: ED3, stem: 'An officer is asked to present Cell-level data to District officials. What best reflects good practice in preparing for this?', options: ['Memorising figures with no supporting documentation', 'Organising accurate, well-labelled data and being ready to explain context, trends and any limitations clearly', 'Presenting only favourable figures and omitting the rest', 'Avoiding any preparation since the data "speaks for itself"'], correct: 1, explanation: 'Good practice is to organise accurate, clearly labelled data and be ready to explain context, trends and limitations — not to selectively present only favourable figures or show up unprepared.' },
    { section: ED3, topic: ED3, stem: 'Why does this role’s broad scope (education, health, social protection, youth and more) make reliable, well-organised record-keeping especially important?', options: ['Breadth of scope makes record-keeping less important', 'With many different programme areas to track, disorganised records are more likely to lead to errors, omissions or confusion across domains — so careful organisation becomes more, not less, important', 'Only one programme area is ever relevant at a time', 'Record-keeping standards are only relevant to narrowly scoped roles'], correct: 1, explanation: 'Precisely because this role spans many programme areas, disorganised records are more likely to cause errors or confusion across domains, making careful, systematic record-keeping especially important here.' },
    { section: ED3, topic: ED3, stem: 'A new officer takes over the role mid-year from a predecessor. Why does well-maintained documentation from the previous officer matter in this situation?', options: ['It does not matter; a new officer should start entirely from scratch', 'It allows the new officer to understand ongoing cases, prior decisions and historical context, supporting continuity of service to the community', 'Documentation from a predecessor should always be discarded', 'Continuity of records is irrelevant to service quality'], correct: 1, explanation: 'Well-maintained documentation lets an incoming officer understand ongoing cases and historical context quickly, supporting continuity of service to the community rather than starting blind.' },
    { section: ED3, topic: ED3, stem: 'What is the relationship between accurate record-keeping and the "results-oriented" competency expected of this role?', options: ['The two are unrelated', 'Accurate records make it possible to actually measure whether interventions are achieving results, which is necessary to demonstrate and improve on results over time', 'Record-keeping and results-orientation work against each other', 'Results can be demonstrated without any supporting records'], correct: 1, explanation: 'Accurate records are what make it possible to actually measure whether interventions are achieving results — without them, claiming to be results-oriented would have no real evidence behind it.' },
    { section: ED3, topic: ED3, stem: 'A Cell’s reporting backlog has grown to 3 overdue reports. What should guide the order in which they are addressed?', options: ['Alphabetical order of report titles, with no other consideration', 'Urgency and consequence of delay (e.g. a report feeding an imminent District decision should likely come before a lower-stakes routine report), discussed with a supervisor if unclear', 'Whichever report is shortest to write, regardless of importance', 'All reports should be abandoned since the backlog is already large'], correct: 1, explanation: 'Prioritising by urgency and the consequences of delay — checking with a supervisor if the priority is unclear — is a more sound basis for sequencing overdue work than report length or alphabetical order alone.' },
    { section: ED3, topic: ED3, stem: 'Why might it be useful to keep brief notes on the reasoning behind unusual or borderline decisions recorded during fieldwork, not just the final decision itself?', options: ['Notes on reasoning serve no purpose', 'They support consistency if a similar case arises again, and make it possible to explain or review the decision later if questioned', 'Only the final decision is ever relevant, never the reasoning', 'Recording reasoning is explicitly discouraged'], correct: 1, explanation: 'Brief notes on reasoning support consistency for future similar cases and make it possible to explain or review a decision later, which is valuable for both accountability and learning.' },
    { section: ED3, topic: ED3, stem: 'An officer’s weekly reporting takes 3 hours, and monthly consolidated reporting takes an additional 5 hours once a month. Roughly how many total reporting hours does the officer spend in a 4-week month?', options: ['15 hours', '17 hours', '19 hours', '21 hours'], correct: 1, explanation: 'Weekly: 3 × 4 = 12 hours. Plus the monthly report: 12 + 5 = 17 hours.' },
    { section: ED3, topic: ED3, stem: 'Which best reflects the appropriate use of "knowledge/awareness" (a listed psychometric domain) in the context of this role’s reporting duties?', options: ['Having no need to understand the subject matter being reported on', 'Understanding the context and meaning behind the data being reported, not just mechanically recording numbers, so reports are accurate and genuinely useful', 'Awareness only matters for senior officials, not Cell-level staff', 'Data should be reported without any contextual understanding'], correct: 1, explanation: 'Genuinely understanding the context and meaning behind the data — not just mechanically entering numbers — supports more accurate, genuinely useful reporting, which is what this psychometric domain is getting at in practice.' },
    { section: ED4, topic: ED4, stem: 'A mobilisation campaign is planned during the harvest season, when many residents are occupied with farming. What is a sensible consideration before finalising the timing?', options: ['Timing is irrelevant to turnout', 'Consider scheduling around residents’ availability (e.g. avoiding peak farming demands) to maximise genuine participation', 'Always schedule campaigns at the most inconvenient time, deliberately', 'Cancel all mobilisation activities during harvest season permanently'], correct: 1, explanation: 'Being mindful of residents’ availability, such as avoiding peak farming periods where practical, supports higher genuine participation rather than scheduling without regard to the community’s actual circumstances.' },
    { section: ED4, topic: ED4, stem: 'Why might using multiple communication channels (e.g. in-person meetings, local radio, community leaders) be more effective for a mobilisation campaign than relying on just one?', options: ['Using multiple channels is never more effective', 'Different residents access information differently, so combining channels increases the chance that the message actually reaches and resonates with a wider audience', 'Only one channel is ever permitted by policy', 'Multiple channels always confuse the message with no benefit'], correct: 1, explanation: 'Because residents access information in different ways, combining channels (in-person, radio, trusted local leaders) increases the likelihood that the message reaches and resonates with a broader cross-section of the community.' },
    { section: ED4, topic: ED4, stem: 'A mobilisation session is attended mostly by older residents, with few young people present despite the topic (youth programmes) being directly relevant to them. What is a reasonable adjustment for future sessions?', options: ['Conclude that young people are simply not interested and stop trying', 'Investigate why young people are not attending (timing, venue, messaging channels) and adjust the approach accordingly to reach them more effectively', 'Keep the exact same approach indefinitely with no adjustment', 'Exclude young people from future sessions entirely'], correct: 1, explanation: 'Rather than assuming disinterest, investigating the actual barriers (timing, venue, how the message is communicated) and adjusting the approach is more likely to improve turnout among the intended audience.' },
    { section: ED4, topic: ED4, stem: 'What is a reasonable indicator of a literacy mobilisation campaign’s success beyond attendance at the launch event?', options: ['No further indicators are ever needed', 'Sustained enrolment and attendance in the literacy classes over subsequent weeks/months, not just turnout at the initial event', 'Only the number of posters printed', 'The campaign’s success cannot be measured in any way'], correct: 1, explanation: 'Sustained enrolment and attendance over time is a far more meaningful indicator of a campaign’s real success than turnout at a single launch event, which only measures initial interest.' },
    { section: ED4, topic: ED4, stem: 'A Cell plans 5 mobilisation sessions, each expected to reach about 35 people. Approximately how many total contacts does this represent, assuming no overlap between sessions?', options: ['150', '160', '175', '185'], correct: 2, explanation: '5 × 35 = 175.' },
    { section: ED4, topic: ED4, stem: 'Why should an officer be cautious about assuming a mobilisation campaign has failed just because immediate behaviour change is not observed right away?', options: ['Behaviour change should always happen instantly, with no exceptions', 'Behaviour change often takes time and repeated reinforcement, so immediate absence of change does not necessarily mean the campaign had no effect', 'Mobilisation campaigns never produce any real change under any circumstances', 'There is no need for caution in drawing conclusions quickly'], correct: 1, explanation: 'Behaviour change is often gradual and may require repeated reinforcement, so judging a campaign a failure based only on an immediate lack of visible change can be premature and inaccurate.' },
    { section: ED4, topic: ED4, stem: 'Which best reflects "adaptability and flexibility" (a listed competency/psychometric domain) in the context of running community mobilisation activities?', options: ['Rigidly following the original plan regardless of changing circumstances', 'Adjusting the approach when circumstances change (e.g. low turnout, weather, competing events) while still working toward the campaign’s underlying goals', 'Refusing to ever change a plan once set', 'Abandoning the campaign’s goals entirely at the first sign of difficulty'], correct: 1, explanation: 'Adaptability and flexibility mean adjusting the approach as circumstances genuinely require, while still working toward the campaign’s underlying goals — not rigid adherence to a plan regardless of changing conditions, nor abandoning the goal altogether.' },
    { section: ED4, topic: ED4, stem: 'A mobilisation campaign on sanitation and hygiene is planned alongside the role’s other duties around health monitoring. Why does combining messaging across related topics (sanitation, hygiene, health) make practical sense here?', options: ['These topics are entirely unrelated to each other', 'They are closely connected aspects of community wellbeing, so coordinated messaging can reinforce understanding and avoid giving residents fragmented, inconsistent information', 'Combining topics is prohibited by policy', 'Each topic must always be addressed in a completely separate campaign with no connection drawn between them'], correct: 1, explanation: 'Sanitation, hygiene and health are closely connected aspects of community wellbeing; coordinated messaging across them can reinforce understanding rather than presenting residents with fragmented, disconnected information.' },
    { section: ED4, topic: ED4, stem: 'Why is it useful for an officer to gather informal feedback from residents after a mobilisation session (e.g. what they found clear or confusing)?', options: ['Feedback is never useful and should not be sought', 'It helps identify what worked and what did not, informing improvements to future sessions', 'Feedback should only ever be sought from officials, never from ordinary residents', 'Feedback collection is prohibited by policy'], correct: 1, explanation: 'Gathering informal feedback helps identify what worked well and what did not in a session, which directly informs improvements to how future mobilisation activities are designed and delivered.' },
    { section: ED4, topic: ED4, stem: 'What is the most appropriate overall framing for this role’s community mobilisation duties, consistent with "client/citizen focus" as a required competency?', options: ['Mobilisation exists to make the officer’s job easier, with residents’ interests a secondary concern', 'Mobilisation exists to genuinely inform, engage and support residents in accessing programmes and improving outcomes relevant to their own lives', 'Mobilisation is purely a box-ticking exercise with no real citizen benefit intended', 'Residents’ own preferences and context should play no role in how mobilisation is designed'], correct: 1, explanation: 'Consistent with a citizen-focused approach, mobilisation duties exist to genuinely inform, engage and support residents in accessing programmes relevant to their own lives — not merely to satisfy a procedural requirement.' },
    { section: ED4, topic: ED4, stem: 'A community mobilisation campaign reaches 220 residents across 4 villages in the Cell. If the villages have populations of 300, 260, 340 and 280, what overall proportion of the total village population was reached?', options: ['About 16%', 'About 18%', 'About 20%', 'About 22%'], correct: 1, explanation: 'Total population = 300+260+340+280 = 1,180. 220 ÷ 1,180 ≈ 0.186, or about 18.6%, closest to about 18%.' },
    { section: ED4, topic: ED4, stem: 'Why might involving school staff directly in a literacy or education mobilisation campaign (rather than the officer acting alone) strengthen its effectiveness?', options: ['School staff have no relevant credibility on education topics', 'School staff bring direct expertise and credibility on education matters, and can reach parents through existing school channels, complementing the officer’s community-level role', 'Involving school staff is prohibited by policy', 'Mobilisation campaigns should always be run by a single person with no collaboration'], correct: 1, explanation: 'School staff bring subject-matter credibility and can reach parents through existing school channels (such as parent meetings), complementing the officer’s broader community-level mobilisation role.' },
    { section: ED4, topic: ED4, stem: 'A mobilisation campaign aims to increase ECD centre enrolment. Which outcome measure would best demonstrate real impact over the following term?', options: ['The number of campaign flyers printed', 'The actual change in ECD enrolment and attendance figures compared with the prior term', 'The officer’s personal opinion of how the campaign felt', 'The length of the campaign event in hours'], correct: 1, explanation: 'Comparing actual ECD enrolment and attendance figures before and after the campaign is a concrete outcome measure, unlike output measures (flyers printed, event length) or subjective impressions.' },
    { section: ED4, topic: ED4, stem: 'Why is it reasonable to tailor mobilisation messaging differently for different groups (e.g. youth, women, people with disabilities) rather than using one identical message for everyone?', options: ['Tailoring messages is never appropriate', 'Different groups may face different barriers or have different concerns, so messaging that addresses their specific context is more likely to be effective and inclusive', 'Only one group in the community ever matters', 'Tailoring messages contradicts the goal of inclusiveness'], correct: 1, explanation: 'Because different groups can face different barriers or concerns, tailoring messaging to address their specific context — while still reaching everyone — supports both effectiveness and genuine inclusiveness.' },
    { section: ED4, topic: ED4, stem: 'A mobilisation session planned for 2 hours runs over by 45 minutes due to active community discussion. What is a reasonable way to view this, assuming the extra time was genuinely productive?', options: ['It is always a failure of planning, regardless of context', 'Reasonable flexibility, since productive engagement is the actual goal — though future planning could allow more buffer time if this is a recurring pattern', 'The session should have been cut off exactly at 2 hours no matter what', 'Running over time is never acceptable under any circumstances'], correct: 1, explanation: 'If the extra time reflected genuine, productive engagement, some flexibility is reasonable, though noticing a recurring pattern could usefully inform better time allocation in future planning.' },
    { section: ED4, topic: ED4, stem: 'What is a practical reason for keeping a simple attendance record at mobilisation sessions, beyond just general interest in numbers?', options: ['Attendance records serve no practical purpose', 'They provide concrete data to assess reach and participation trends over time, supporting the role’s broader reporting and monitoring duties', 'Attendance should never be recorded for privacy reasons', 'Only the officer’s memory should be relied on, never written records'], correct: 1, explanation: 'Attendance records provide concrete data on reach and participation trends over time, feeding directly into the role’s broader reporting and monitoring responsibilities.' },
    { section: ED4, topic: ED4, stem: 'A campaign message about school feeding benefits is translated into Kinyarwanda for the session. Why does this matter for effective community mobilisation?', options: ['Translation is unnecessary since all residents understand every language equally well', 'Communicating in the language residents are most comfortable with supports clearer understanding and more genuine engagement', 'Only official languages used in national government documents should ever be spoken at community events', 'Language choice has no bearing on how well a message is understood'], correct: 1, explanation: 'Communicating in the language residents are most comfortable with — Kinyarwanda, in most community settings — supports clearer understanding and more genuine engagement, consistent with effective, citizen-focused communication.' },
    { section: ED4, topic: ED4, stem: 'Two consecutive mobilisation campaigns on education recorded 48% and 61% turnout among the target population. What is the percentage-point improvement?', options: ['11', '12', '13', '14'], correct: 2, explanation: '61 − 48 = 13 percentage points.' },
  ],
};

// ───────────────────────────── Mock 3: Health, nutrition, youth & community programmes

const HN1 = 'Health, hygiene, sanitation and nutrition';
const HN2 = 'Youth, gender, disability and inclusion programmes';
const HN3 = 'Sports, innovation, talent detection and delinquency prevention';
const HN4 = 'Child protection and community mobilisation';

export const hcsdMock3: TestDef = {
  country: 'RW',
  jobDeadlineAt: DEADLINE,
  category: 'government-administration',
  profession: PROFESSION,
  authority: 'MINALOC',
  slug: 'human-capital-social-development-officer-mock-exam-3',
  title: 'Human Capital & Social Development Officer — Mock Exam 3',
  summary: 'Practice monitoring health, hygiene, sanitation and nutrition interventions; youth, gender and disability-inclusion programmes; sports, innovation and delinquency prevention; and child-protection community mobilisation.',
  free: false,
  difficulty: 'STANDARD',
  minutes: 120,
  sections: [{ name: HN1 }, { name: HN2 }, { name: HN3 }, { name: HN4 }],
  questions: [
    { section: HN1, topic: HN1, stem: 'Monitoring "health, hygiene, and sanitation" interventions at Cell level, as listed among this role’s duties, most directly supports which broader goal?', options: ['Increasing tax revenue', 'Reducing preventable illness and improving community wellbeing, which in turn supports education and economic participation', 'Replacing the role of health centres entirely', 'Setting national health insurance premiums'], correct: 1, explanation: 'Monitoring health, hygiene and sanitation interventions supports reducing preventable illness and improving wellbeing — outcomes that also reinforce school attendance and economic participation, consistent with the role’s human-capital focus.' },
    { section: HN1, topic: HN1, stem: 'Who typically leads the primary delivery of health services at the community level in Rwanda, with the social development officer playing a monitoring/coordinating role?', options: ['The social development officer personally delivers all health services', 'Health centres, community health workers and the formal health system, with the officer monitoring and supporting coordination rather than delivering clinical care', 'The Ministry of Finance', 'No one; health services are not delivered locally'], correct: 1, explanation: 'Clinical and community health service delivery is led by health centres, community health workers and the formal health system; the officer’s role is monitoring and coordination support, not delivering clinical care directly.' },
    { section: HN1, topic: HN1, stem: 'A community reports a cluster of diarrheal illness cases, often linked to poor sanitation or water quality. What is an appropriate response for a social development officer?', options: ['Ignore it since it is purely a health-centre matter', 'Report it promptly to relevant health authorities, support any coordinated community sanitation response, and monitor the situation', 'Attempt to diagnose or treat patients personally', 'Dismiss the reports without any follow-up'], correct: 1, explanation: 'The appropriate response is prompt reporting to health authorities and supporting coordinated action (e.g. community sanitation measures), not attempting clinical diagnosis/treatment or ignoring the reports.' },
    { section: HN1, topic: HN1, stem: 'Why might household-level sanitation facilities (such as latrines) be tracked as part of this role’s monitoring duties?', options: ['Sanitation facilities have no bearing on community health', 'Access to basic sanitation is linked to disease prevention and overall public health, making it a relevant indicator for community wellbeing monitoring', 'Tracking facilities is solely an engineering concern with no social relevance', 'This indicator is tracked only for aesthetic reasons'], correct: 1, explanation: 'Access to basic sanitation facilities is closely linked to disease prevention, making it a relevant indicator to track as part of monitoring community health and hygiene outcomes.' },
    { section: HN1, topic: HN1, stem: 'In the context of this role, what would be the most appropriate first action if a household is found to have no access to improved sanitation and appears unaware of available support?', options: ['Take no action, as this falls entirely outside the role', 'Raise awareness of available support or guidance and refer the household to the appropriate programme or service', 'Report the household to law enforcement', 'Build the sanitation facility personally without informing anyone'], correct: 1, explanation: 'A reasonable, duty-consistent response is raising awareness and making an appropriate referral to available support or guidance — not law enforcement involvement or taking on direct construction work personally.' },
    { section: HN1, topic: HN1, stem: 'A nutrition-monitoring visit finds a child showing visible signs of poor growth for their age. What is the correct next step?', options: ['Make a clinical diagnosis personally and prescribe treatment', 'Refer the case to the appropriate health service for proper assessment, and follow up to see that the referral was acted on', 'Ignore it since this is outside the social development officer’s remit entirely', 'Record it but take no further action or follow-up'], correct: 1, explanation: 'The appropriate response is a referral to the proper health service for clinical assessment, with follow-up to confirm the referral was acted on — not attempting diagnosis personally nor ignoring the case.' },
    { section: HN1, topic: HN1, stem: 'Why is coordination between social development officers and community health workers particularly valuable for nutrition-related monitoring?', options: ['The two roles have no overlap in practice', 'Community health workers often have direct, ongoing contact with households on health matters, so coordinating with them helps identify and follow up on nutrition concerns more effectively', 'Coordination between these two roles is discouraged by policy', 'Nutrition is exclusively a hospital-level concern with no community role'], correct: 1, explanation: 'Community health workers typically have direct, regular contact with households on health matters; coordinating with them helps the officer identify and follow up on nutrition concerns more effectively than working in isolation.' },
    { section: HN1, topic: HN1, stem: 'A Cell reports 54 cases of a preventable illness this quarter, up from 38 last quarter. What is the percentage increase?', options: ['32%', '37%', '42%', '47%'], correct: 2, explanation: '(54 − 38) ÷ 38 = 16 ÷ 38 ≈ 0.421, or about 42%.' },
    { section: HN1, topic: HN1, stem: 'What is a reasonable interpretation of "monitoring interventions to prevent and reduce malnutrition and stunting," one of this role’s listed duties?', options: ['Personally running clinical nutrition treatment', 'Tracking whether relevant nutrition-related interventions (e.g. school feeding, nutrition education, referrals) are being implemented and identifying households or children who may need additional support', 'This duty has no relevance to the role', 'Only monitoring is required, with no expectation of ever acting on findings'], correct: 1, explanation: 'This duty is about tracking whether nutrition-related interventions are being implemented and identifying households or children needing support — not delivering clinical nutrition treatment directly.' },
    { section: HN1, topic: HN1, stem: 'A community health campaign on handwashing reaches 180 households out of 240 in the target area. What percentage of households were reached?', options: ['65%', '70%', '75%', '80%'], correct: 2, explanation: '180 ÷ 240 = 0.75, or 75%.' },
    { section: HN1, topic: HN1, stem: 'Why would an officer need basic awareness of common preventable-illness risk factors (e.g. poor sanitation, unsafe water) even without clinical training?', options: ['No awareness is needed since this is entirely outside the role', 'Basic awareness helps the officer recognise situations warranting referral or coordinated action, supporting the monitoring and referral aspects of the role', 'Clinical-level expertise is required before any awareness is useful', 'This awareness is only relevant to doctors, never to social development staff'], correct: 1, explanation: 'Basic awareness — without needing clinical expertise — helps the officer recognise situations that warrant a referral or coordinated response, which is central to the monitoring and referral aspects of this role.' },
    { section: HN1, topic: HN1, stem: 'A nutrition programme target is to screen 300 children this quarter; 216 have been screened with 3 weeks remaining in the quarter. What percentage of the target remains to be screened?', options: ['24%', '26%', '28%', '30%'], correct: 2, explanation: '(300 − 216) ÷ 300 = 84 ÷ 300 = 0.28, or 28%.' },
    { section: HN1, topic: HN1, stem: 'What role might the officer play in supporting a community sanitation improvement campaign, consistent with monitoring (not delivery) duties?', options: ['Personally constructing all sanitation infrastructure', 'Supporting mobilisation and awareness, monitoring progress, and coordinating with relevant technical or health actors responsible for delivery', 'Taking no role of any kind', 'Setting the national sanitation budget'], correct: 1, explanation: 'The officer’s role is to support mobilisation and awareness, monitor progress, and coordinate with the technical or health actors responsible for actual delivery — not to personally construct infrastructure or set national budgets.' },
    { section: HN1, topic: HN1, stem: 'Why is it important to disaggregate nutrition or health data by age group (e.g. under-5 children versus adults) rather than reporting only a combined Cell-wide figure?', options: ['Disaggregation adds no useful information', 'Different age groups face different risks and intervention needs (e.g. stunting prevention focuses heavily on under-5 children), so disaggregated data supports more targeted, effective action', 'Only combined figures are ever useful for planning', 'Age-based disaggregation is prohibited by policy'], correct: 1, explanation: 'Because risks and intervention needs differ by age group — stunting prevention, for instance, is especially critical for under-5 children — disaggregated data allows more targeted, effective action than a single combined figure.' },
    { section: HN1, topic: HN1, stem: 'A household reports they stopped attending a nutrition support programme because the clinic is too far to reach regularly. What is a reasonable, citizen-focused response?', options: ['Dismiss the concern as not the officer’s problem', 'Acknowledge the barrier, explore whether any closer alternative or outreach option exists, and relay the access concern through appropriate channels if a systemic gap is identified', 'Tell the household to simply try harder', 'Remove the household from all programme records'], correct: 1, explanation: 'A citizen-focused response acknowledges the real barrier, explores practical alternatives, and raises systemic access gaps through the appropriate channel — rather than dismissing the concern or penalising the household.' },
    { section: HN1, topic: HN1, stem: 'Of 95 households surveyed on water access, 19 reported needing to travel more than 30 minutes to the nearest clean water source. What percentage is this?', options: ['18%', '20%', '22%', '24%'], correct: 1, explanation: '19 ÷ 95 = 0.20, or 20%.' },
    { section: HN1, topic: HN1, stem: 'Why might seasonal factors (e.g. rainy versus dry season) be relevant to interpreting health or sanitation data over the course of a year?', options: ['Seasonal factors never affect health or sanitation outcomes', 'Certain conditions (e.g. waterborne illness, water scarcity) can vary meaningfully by season, so interpreting trends without this context could lead to incorrect conclusions', 'Data should always be interpreted identically regardless of season', 'Seasonal variation is only relevant to agricultural data, never health data'], correct: 1, explanation: 'Conditions such as waterborne illness risk or water scarcity can genuinely vary by season; ignoring this context when interpreting data trends risks drawing misleading conclusions about underlying causes.' },
    { section: HN1, topic: HN1, stem: 'A Cell’s nutrition programme has a budget of RWF 960,000 for the quarter, to be split evenly across 4 planned activities. How much is allocated per activity?', options: ['RWF 200,000', 'RWF 220,000', 'RWF 240,000', 'RWF 260,000'], correct: 2, explanation: '960,000 ÷ 4 = 240,000.' },
    { section: HN1, topic: HN1, stem: 'What is a reasonable way to balance "client/citizen focus" with the limits of the officer’s own role when a resident raises a serious, urgent health concern?', options: ['Attempt to handle it entirely alone without involving health services', 'Respond with genuine concern, facilitate prompt referral to the appropriate health service, and follow up appropriately — recognising the boundary of the officer’s own expertise', 'Dismiss the concern as unimportant', 'Delay any response indefinitely'], correct: 1, explanation: 'Being citizen-focused while respecting professional boundaries means responding with genuine concern and facilitating a prompt, appropriate referral — not attempting to personally resolve a matter requiring health expertise, nor dismissing or delaying it.' },
    { section: HN1, topic: HN1, stem: 'A community hygiene campaign distributed information to 420 households, and a follow-up survey found 315 reported improved handwashing practices. What percentage reported improvement?', options: ['68%', '70%', '72%', '75%'], correct: 3, explanation: '315 ÷ 420 = 0.75, or 75%.' },
    { section: HN1, topic: HN1, stem: 'Why is ongoing monitoring (not a one-time check) appropriate for health, hygiene and sanitation interventions?', options: ['A one-time check is always sufficient and ongoing monitoring is wasteful', 'Conditions and behaviours can change over time (e.g. new households, seasonal risks, lapses in practice), so ongoing monitoring helps catch and address problems as they arise', 'Ongoing monitoring is prohibited for health-related matters', 'Health and sanitation conditions never change once assessed'], correct: 1, explanation: 'Because conditions and behaviours can change over time — new households moving in, seasonal risks, or lapses in good practice — ongoing monitoring helps catch and address emerging problems rather than relying on a single outdated check.' },
    { section: HN1, topic: HN1, stem: 'A Cell has 6 villages; a sanitation-coverage survey found access rates of 70%, 85%, 60%, 90%, 75% and 80%. What is the average sanitation-coverage rate across the Cell?', options: ['75%', '76.7%', '78%', '80%'], correct: 1, explanation: '(70+85+60+90+75+80) ÷ 6 = 460 ÷ 6 ≈ 76.7%.' },
    { section: HN1, topic: HN1, stem: 'Which best reflects appropriate professional conduct if a health-related concern an officer is monitoring involves a household’s private medical information?', options: ['Share the information freely in community meetings', 'Handle the information with appropriate discretion and confidentiality, sharing only what is necessary with the relevant professionals for proper follow-up', 'Record nothing at all to avoid any privacy concern, even when follow-up requires documentation', 'Publicly post the information to raise awareness'], correct: 1, explanation: 'Handling sensitive health information with discretion and sharing only what is necessary with relevant professionals balances proper follow-up with respect for household privacy — public sharing or complete non-documentation are both inappropriate extremes.' },
    { section: HN1, topic: HN1, stem: 'A Cell’s stunting-prevention outreach reached 64 children out of an estimated 80 under-5 children with relevant risk factors. What percentage of the at-risk group was reached?', options: ['75%', '78%', '80%', '82%'], correct: 2, explanation: '64 ÷ 80 = 0.80, or 80%.' },
    { section: HN1, topic: HN1, stem: 'Why might combining a nutrition-awareness session with an existing community gathering (e.g. a VUP public-works day) be a practical approach, consistent with efficient resource use?', options: ['Combining activities is never practical', 'It can reach a relevant audience efficiently without requiring an entirely separate event, provided the context and timing are appropriate', 'Nutrition topics should never be discussed alongside any other activity', 'This approach is prohibited by policy'], correct: 1, explanation: 'Where appropriate, combining a nutrition-awareness session with an existing gathering can efficiently reach a relevant audience without the resource cost of organising an entirely separate event.' },
    { section: HN1, topic: HN1, stem: 'A household’s child missed 3 of 5 scheduled growth-monitoring visits this year. What percentage of visits were missed?', options: ['50%', '55%', '60%', '65%'], correct: 2, explanation: '3 ÷ 5 = 0.60, or 60%.' },
    { section: HN1, topic: HN1, stem: 'What would be the most appropriate response if a household repeatedly misses scheduled nutrition or health follow-up visits?', options: ['Immediately remove the household from all support with no inquiry', 'Follow up to understand the reason (e.g. access barriers, misunderstanding, competing demands) and address it where possible, rather than assuming neglect', 'Take no further action of any kind', 'Publicly criticise the household in a community meeting'], correct: 1, explanation: 'Following up to understand the underlying reason for repeated missed visits — rather than assuming neglect or taking punitive action — reflects a citizen-focused, problem-solving approach consistent with the role.' },
    { section: HN1, topic: HN1, stem: 'Why is it valuable for an officer to know which health facility or community health worker serves a given village within the Cell?', options: ['This information has no practical use', 'It supports faster, more accurate referrals and coordination when a health-related concern is identified during fieldwork', 'Only the health sector itself needs this information', 'This information changes the officer’s job description entirely'], correct: 1, explanation: 'Knowing which facility or community health worker serves a given village supports faster and more accurate referrals and coordination when the officer identifies a health-related concern during routine fieldwork.' },
    { section: HN1, topic: HN1, stem: 'A Cell reports that 7 out of 40 households surveyed lack access to a protected water source. If this rate held across the Cell’s 360 total households, how many would be expected to lack access?', options: ['54', '58', '63', '67'], correct: 2, explanation: 'Rate = 7 ÷ 40 = 17.5%. 17.5% × 360 = 63.' },
    { section: HN2, topic: HN2, stem: 'What is the main purpose of monitoring "youth, women, and people with disabilities activities" at Cell level, as explicitly listed among this role’s duties?', options: ['To exclude these groups from general programmes', 'To ensure these groups’ specific needs and participation are tracked and supported, consistent with inclusive, needs-based social development', 'This duty has no real purpose and is purely symbolic', 'To replace the need for any general community programmes'], correct: 1, explanation: 'This duty exists to ensure the specific needs and participation of youth, women and people with disabilities are tracked and supported, reflecting an inclusive, needs-based approach to social development.' },
    { section: HN2, topic: HN2, stem: 'Why might disability-inclusive programme design require more than simply "allowing" people with disabilities to attend an activity?', options: ['Inclusive design requires nothing beyond a general invitation', 'Genuine inclusion often requires actively considering and addressing practical barriers (e.g. physical accessibility, communication needs) that could otherwise prevent meaningful participation', 'People with disabilities never face any practical barriers to participation', 'Addressing accessibility barriers is outside this role’s scope entirely'], correct: 1, explanation: 'Genuine inclusion typically requires actively addressing practical barriers — such as physical accessibility or communication needs — that could otherwise prevent meaningful participation, not just a general, passive invitation.' },
    { section: HN2, topic: HN2, stem: 'A youth programme in the Cell has consistently low participation from young women compared with young men. What is a reasonable diagnostic step?', options: ['Assume young women are simply not interested and take no further action', 'Investigate possible specific barriers (e.g. timing, safety concerns, household responsibilities, social norms) through direct engagement with young women in the community', 'Cancel the programme entirely', 'Exclude young men from the programme instead'], correct: 1, explanation: 'Investigating specific, concrete barriers through direct engagement with the under-represented group is a more constructive diagnostic step than assuming disinterest or taking drastic, uninvestigated action.' },
    { section: HN2, topic: HN2, stem: 'What does "talent detection," listed among this role’s sports/innovation-related duties, most likely refer to?', options: ['Identifying promising abilities (e.g. in sports or innovation) among youth so they can be supported and connected with further development opportunities', 'Determining which residents are eligible for social protection', 'A health screening process', 'An unrelated term with no real meaning in this context'], correct: 0, explanation: 'Talent detection generally refers to identifying promising abilities among youth — in sports, innovation or related areas — so they can be connected with further development or opportunity pathways.' },
    { section: HN2, topic: HN2, stem: 'Why would monitoring women’s participation specifically (not just overall community participation) be useful for an officer tracking programme effectiveness?', options: ['Monitoring participation by gender is never useful', 'It can reveal whether women are being reached and included as intended, or whether specific barriers are limiting their participation, allowing for a more targeted response', 'Only men’s participation is ever relevant to track', 'Gender-disaggregated monitoring is prohibited by policy'], correct: 1, explanation: 'Gender-disaggregated monitoring can reveal whether women are being reached as intended or whether specific barriers are limiting their participation, which supports a more targeted, effective response.' },
    { section: HN2, topic: HN2, stem: 'A youth programme has 85 registered participants, of whom 34 are young women. What percentage of participants are young women?', options: ['35%', '38%', '40%', '42%'], correct: 2, explanation: '34 ÷ 85 = 0.40, or 40%.' },
    { section: HN2, topic: HN2, stem: 'What would be a reasonable approach if a resident with a physical disability reports difficulty physically accessing the venue used for community meetings?', options: ['Ignore the concern since venues cannot be changed', 'Raise the accessibility concern through the appropriate channel and explore practical alternatives (e.g. a more accessible venue or adapted arrangements) where feasible', 'Tell the resident to simply not attend future meetings', 'Dismiss the concern as not a real issue'], correct: 1, explanation: 'A reasonable, inclusive response is to raise the concern through the appropriate channel and explore practical alternatives where feasible — not to dismiss the issue or effectively exclude the resident from future participation.' },
    { section: HN2, topic: HN2, stem: 'A community innovation initiative for youth identifies 12 promising participants out of 150 who took part in an initial activity. What percentage were identified as promising?', options: ['6%', '7%', '8%', '9%'], correct: 2, explanation: '12 ÷ 150 = 0.08, or 8%.' },
    { section: HN2, topic: HN2, stem: 'Why does Rwanda’s broader human-capital and social-development strategy generally place emphasis on youth, women and people with disabilities as specific focus groups?', options: ['These groups have no particular relevance to human-capital development', 'These groups have historically faced specific barriers to full economic and social participation, so targeted attention can help close gaps and support more inclusive development outcomes', 'Focusing on specific groups contradicts inclusive development', 'This emphasis exists only in sports policy, not broader social policy'], correct: 1, explanation: 'Groups that have historically faced specific participation barriers are often given targeted attention precisely to help close those gaps, supporting more genuinely inclusive development outcomes overall.' },
    { section: HN2, topic: HN2, stem: 'A sports-based talent-detection programme for youth is planned. Why might ensuring girls’ equal access to the programme matter, consistent with "inclusiveness"?', options: ['Girls’ access to sports programmes is irrelevant to inclusiveness', 'Without deliberate attention, participation gaps between girls and boys can persist due to social norms or practical barriers, undermining equal opportunity', 'Sports programmes should only ever be offered to boys', 'Equal access has no bearing on talent-detection effectiveness'], correct: 1, explanation: 'Without deliberate attention to equal access, participation gaps between girls and boys can persist due to social norms or practical barriers, which both undermines equal opportunity and could mean missing genuine talent.' },
    { section: HN2, topic: HN2, stem: 'An officer is monitoring whether a Cell’s youth programmes reach people with disabilities. What is a reasonable first step if current data does not disaggregate participation by disability status?', options: ['Assume the data gap does not matter and leave it unaddressed', 'Work toward including disability status in future data collection, so participation and gaps can actually be tracked and addressed', 'Stop collecting any participation data at all', 'Invent plausible-sounding figures to fill the gap'], correct: 1, explanation: 'Working toward including disability status in future data collection is a constructive response to a genuine data gap, allowing participation and any gaps to be properly tracked and addressed — fabricating figures or ignoring the gap would both be inappropriate.' },
    { section: HN2, topic: HN2, stem: 'A youth skills-training programme has a capacity of 40 but received 68 applications. What percentage of applicants can be accommodated in this cycle?', options: ['About 55%', 'About 59%', 'About 63%', 'About 67%'], correct: 1, explanation: '40 ÷ 68 ≈ 0.588, or about 59%.' },
    { section: HN2, topic: HN2, stem: 'Why might the officer coordinate with organisations specifically focused on disability inclusion when designing community activities?', options: ['Such coordination is unnecessary since all programmes are automatically fully accessible', 'These organisations often have specific expertise on accessibility and inclusion that can help the officer design more genuinely inclusive activities', 'Coordination with specialised organisations is prohibited', 'Disability-focused organisations have no relevant expertise to contribute'], correct: 1, explanation: 'Organisations focused on disability inclusion often bring specific expertise that can help the officer design activities that are genuinely, practically accessible, rather than assuming accessibility by default.' },
    { section: HN2, topic: HN2, stem: 'What is a reasonable way to measure whether a youth programme is genuinely achieving inclusive participation, beyond simply counting total attendees?', options: ['Total attendance alone tells the full story', 'Tracking participation disaggregated by relevant categories (e.g. gender, disability status, age) to see whether specific groups are being reached proportionally', 'No measurement is possible for inclusiveness', 'Inclusiveness cannot be assessed using any data'], correct: 1, explanation: 'Disaggregated participation data — by gender, disability status, age, etc. — gives a much clearer picture of whether specific groups are genuinely being reached, compared with a single total attendance figure.' },
    { section: HN2, topic: HN2, stem: 'A community has 420 youth aged 16-30, of whom 126 are enrolled in some form of skills or vocational programme. What percentage of youth are enrolled?', options: ['25%', '28%', '30%', '32%'], correct: 2, explanation: '126 ÷ 420 = 0.30, or 30%.' },
    { section: HN2, topic: HN2, stem: 'Why might monitoring whether women and people with disabilities hold any leadership or advisory roles in community programmes (not just participant roles) be a relevant indicator of inclusion?', options: ['Leadership representation has no bearing on genuine inclusion', 'Representation in leadership or advisory roles can indicate a deeper, more substantive form of inclusion than participation alone, and can shape how programmes are designed', 'Only participant-level inclusion ever matters', 'Tracking this indicator is prohibited'], correct: 1, explanation: 'Representation in leadership or advisory roles can reflect a more substantive form of inclusion than participation alone, and can also shape how programmes are designed to better serve these groups’ actual needs.' },
    { section: HN2, topic: HN2, stem: 'A disability-inclusion awareness session for community members reached 95 of an estimated 140 relevant stakeholders (local leaders, programme staff, etc.). What percentage was reached?', options: ['62%', '65%', '68%', '71%'], correct: 2, explanation: '95 ÷ 140 ≈ 0.679, or about 68%.' },
    { section: HN2, topic: HN2, stem: 'Which best reflects a balanced approach to monitoring youth, women’s and disability-inclusion programmes, consistent with professionalism and inclusiveness together?', options: ['Focus exclusively on one group and ignore the others entirely', 'Apply consistent, fair monitoring attention across all relevant groups based on their documented needs and participation gaps, without favouring or neglecting any one group arbitrarily', 'Avoid monitoring any specific group to prevent appearing biased', 'Monitor only whichever group is easiest to reach, regardless of actual need'], correct: 1, explanation: 'A balanced, professional and inclusive approach applies consistent monitoring attention across relevant groups based on documented needs and gaps — not arbitrary favouritism, convenience-based focus, or avoiding the topic altogether.' },
    { section: HN1, topic: HN1, stem: 'A Cell’s latest water-quality monitoring report flags one village with contamination risk, out of 5 villages tested. What percentage of tested villages showed contamination risk?', options: ['15%', '20%', '25%', '30%'], correct: 1, explanation: '1 ÷ 5 = 0.20, or 20%.' },
    { section: HN2, topic: HN2, stem: 'A programme supporting people with disabilities has 22 registered participants this year compared with 14 last year. What is the percentage increase?', options: ['47%', '52%', '57%', '62%'], correct: 2, explanation: '(22 − 14) ÷ 14 = 8 ÷ 14 ≈ 0.571, or about 57%.' },
    { section: HN2, topic: HN2, stem: 'A youth mentorship programme pairs mentors with mentees in a 1:4 ratio. If there are 9 mentors, how many mentees can be supported?', options: ['32', '34', '36', '38'], correct: 2, explanation: '9 × 4 = 36.' },
    { section: HN2, topic: HN2, stem: 'Why might it be useful to ask women participants directly what time of day works best for programme sessions, rather than assuming a standard schedule suits everyone?', options: ['Asking participants directly is never useful', 'Household and caregiving responsibilities can affect availability differently across individuals, so direct input helps design a schedule that genuinely supports participation', 'Scheduling should never be adapted for any group', 'Only programme staff’s convenience should determine scheduling'], correct: 1, explanation: 'Because responsibilities and availability can genuinely differ, asking participants directly helps design a schedule more likely to support real participation, rather than assuming one standard time suits everyone.' },
    { section: HN2, topic: HN2, stem: 'A disability-inclusive sports session had 18 participants with disabilities out of 60 total participants. What percentage of participants had a disability?', options: ['25%', '28%', '30%', '32%'], correct: 2, explanation: '18 ÷ 60 = 0.30, or 30%.' },
    { section: HN2, topic: HN2, stem: 'What is a reasonable response if a youth programme’s results consistently show strong outcomes for participants from wealthier households but weak outcomes for the poorest participants?', options: ['Conclude the programme is working well overall and take no further action', 'Investigate whether poorer participants face additional barriers (e.g. cost of materials, transport, competing work demands) and consider adjustments to better support them', 'Exclude poorer participants from future cycles', 'Assume poorer participants are simply less capable'], correct: 1, explanation: 'A pattern like this warrants investigating additional barriers poorer participants may face and considering practical adjustments — not excluding them or drawing unfounded conclusions about capability.' },
    { section: HN2, topic: HN2, stem: 'A community has 95 registered people with disabilities, of whom 38 are currently engaged in at least one social-development programme. What percentage are currently engaged?', options: ['38%', '40%', '42%', '44%'], correct: 1, explanation: '38 ÷ 95 = 0.40, or 40%.' },
    { section: HN2, topic: HN2, stem: 'Why might an officer track not just whether a programme exists for youth, women or people with disabilities, but also whether it is actually being used?', options: ['Usage data is irrelevant once a programme has been established', 'A programme that exists on paper but is barely used may indicate access barriers or awareness gaps that need addressing, which pure existence data would not reveal', 'Existence of a programme always guarantees it is working well', 'Tracking usage is prohibited once a programme is launched'], correct: 1, explanation: 'A programme that exists but has low actual usage can signal access barriers or awareness gaps — something that simply confirming the programme’s existence would not reveal, making usage tracking an important complement.' },
    { section: HN3, topic: HN3, stem: 'What is the likely intent behind listing "sports, innovation and talent detection" alongside more traditional social-development duties on this posting?', options: ['Sports and innovation have no connection to human-capital development', 'Recognising that developing young people’s talents and positive engagement (through sports, innovation, etc.) is itself part of building human capital and can also support delinquency prevention', 'This item was included by mistake and has no real relevance', 'Only elite athletes are relevant to this duty'], correct: 1, explanation: 'Supporting young people’s talents and positive engagement through sports and innovation is itself a form of human-capital development, and can also contribute to keeping youth positively occupied, supporting delinquency prevention.' },
    { section: HN3, topic: HN3, stem: 'Why might sports and recreational activities be linked to "eradicating delinquency," another duty listed for this role?', options: ['There is no plausible connection between the two', 'Constructive, positive activities can occupy young people’s time and build social connections, which is widely seen as supportive of reducing risk factors associated with delinquent behaviour', 'Sports activities are known to increase delinquency', 'Delinquency prevention has nothing to do with youth engagement'], correct: 1, explanation: 'Constructive activities like sports can occupy young people’s time positively and build social connections, which is a commonly cited supportive factor in reducing risk factors linked to delinquent behaviour.' },
    { section: HN3, topic: HN3, stem: 'What would be a reasonable first step for an officer identifying a young person with notable sporting or innovative talent during a community activity?', options: ['Ignore the talent entirely since it is outside the officer’s scope', 'Note the talent and explore appropriate pathways or programmes (e.g. referral to relevant coaches, innovation hubs, or youth development schemes) that could support further development', 'Personally coach the young person with no referral to relevant specialists', 'Discourage the young person from pursuing the talent'], correct: 1, explanation: 'A reasonable response is noting the talent and exploring appropriate referral pathways to relevant specialists or programmes — not personally taking on a coaching role outside the officer’s expertise, nor ignoring or discouraging the talent.' },
    { section: HN3, topic: HN3, stem: 'A Cell runs a youth sports programme reaching 60 participants, of whom 9 are later identified as having notable talent warranting further support. What percentage of participants were identified this way?', options: ['12%', '15%', '18%', '20%'], correct: 1, explanation: '9 ÷ 60 = 0.15, or 15%.' },
    { section: HN3, topic: HN3, stem: 'What does "eradicating delinquency" as a monitored duty most plausibly involve at Cell level, given this role’s broader scope?', options: ['Direct law-enforcement action against young people', 'Monitoring and supporting preventive interventions (positive youth engagement, community mobilisation, referral for at-risk youth) rather than direct policing', 'This duty has nothing to do with youth at all', 'Punishing households for a child’s behaviour with no further engagement'], correct: 1, explanation: 'Given the role’s broader social-development focus, this duty is best understood as monitoring and supporting preventive interventions — not direct law-enforcement action, which is handled by other institutions.' },
    { section: HN3, topic: HN3, stem: 'An officer notices a group of out-of-school youth spending unstructured time with no access to positive activities. What is a reasonable, duty-consistent response?', options: ['Take no action, since this is unrelated to the role', 'Explore options for connecting them with relevant programmes (e.g. vocational training, sports, mentorship) and understand underlying reasons they are out of school', 'Report them to authorities with no further engagement or support', 'Assume they are destined for delinquent behaviour with no intervention attempted'], correct: 1, explanation: 'A constructive response explores connecting these youth with relevant positive programmes and seeks to understand why they are out of school, consistent with the role’s preventive, supportive focus.' },
    { section: HN3, topic: HN3, stem: 'Why might "innovation" be specifically mentioned alongside "talent detection" for youth in this context?', options: ['Innovation has no connection to youth development', 'Identifying and nurturing young people’s innovative/entrepreneurial potential is seen as another pathway to building human capital and economic opportunity, alongside sports', 'Innovation only applies to established businesses, never youth', 'This term was included with no intended meaning'], correct: 1, explanation: 'Identifying and nurturing innovative or entrepreneurial potential among youth is another recognised pathway to building human capital and future economic opportunity, complementing sports-based talent detection.' },
    { section: HN3, topic: HN3, stem: 'A Cell’s youth innovation initiative receives 28 project ideas, of which 7 are selected for further mentorship support. What percentage of submitted ideas were selected?', options: ['20%', '25%', '28%', '30%'], correct: 1, explanation: '7 ÷ 28 = 0.25, or 25%.' },
    { section: HN3, topic: HN3, stem: 'What is a reasonable way to balance encouraging participation in sports/innovation activities with the "inclusiveness" value, so these opportunities do not become limited to a narrow group?', options: ['Restrict activities to only the most naturally talented youth from the start', 'Design activities with broad initial access, so talent can be identified fairly across the whole youth population rather than only among those already favoured or connected', 'Exclude youth from poorer households by default', 'Inclusiveness is irrelevant to sports and innovation activities'], correct: 1, explanation: 'Designing activities with broad initial access helps ensure talent can be identified fairly across the whole youth population, rather than the opportunity being effectively limited to an already-advantaged or well-connected group.' },
    { section: HN3, topic: HN3, stem: 'A sports programme budget of RWF 540,000 is split across 3 age-group categories evenly. How much is allocated per category?', options: ['RWF 160,000', 'RWF 170,000', 'RWF 180,000', 'RWF 190,000'], correct: 2, explanation: '540,000 ÷ 3 = 180,000.' },
    { section: HN3, topic: HN3, stem: 'Why might coordinating with school staff be useful for identifying youth at risk of disengagement who might benefit from sports, innovation or other positive-engagement programmes?', options: ['Schools have no relevant information on this topic', 'School staff may notice early signs of disengagement (attendance drop, behavioural changes) that could prompt a timely, supportive referral to relevant programmes', 'Coordination with schools on this topic is prohibited', 'Disengagement can only ever be identified by the officer working entirely alone'], correct: 1, explanation: 'School staff are often well placed to notice early signs of disengagement, such as changes in attendance or behaviour, making coordination with them valuable for timely, supportive referrals.' },
    { section: HN3, topic: HN3, stem: 'A youth mentorship/talent programme tracked outcomes for 50 participants over a year: 38 reported improved skills or opportunities. What percentage reported improvement?', options: ['70%', '74%', '76%', '78%'], correct: 2, explanation: '38 ÷ 50 = 0.76, or 76%.' },
    { section: HN3, topic: HN3, stem: 'What is a reasonable interpretation of "supporting" sports, innovation and talent-detection activities as a monitoring/coordination duty, rather than a technical/coaching duty?', options: ['The officer is expected to personally coach every sport and technical skill', 'The officer helps organise, mobilise participation, connect youth with the right specialists or resources, and monitor outcomes — without needing to be a technical expert in every activity', 'This duty requires no real involvement at all', 'The officer should discourage any technical specialist involvement'], correct: 1, explanation: 'The officer’s role is organisational and coordinating — mobilising participation, connecting youth with relevant specialists or resources, and monitoring outcomes — not personally serving as a technical expert in every sport or innovation area.' },
    { section: HN3, topic: HN3, stem: 'A community reports a recent rise in minor youth-related incidents. What combination of this role’s duties would be most relevant to respond constructively?', options: ['None — this is entirely a police matter with no role for a social development officer', 'Supporting positive youth engagement (sports, innovation, mentorship), community mobilisation, and coordinating with relevant actors (schools, families, where appropriate, law enforcement) on prevention', 'Publicly shaming the youth involved', 'Ignoring the trend entirely'], correct: 1, explanation: 'A constructive, duty-consistent response combines supporting positive youth engagement, community mobilisation and coordination with relevant actors on prevention — not public shaming or disengagement from the issue.' },
    { section: HN3, topic: HN3, stem: 'Why might tracking participation trends in youth sports/innovation programmes over several years be more informative than looking at just one year?', options: ['A single year always tells the complete story', 'Multi-year trends help distinguish a genuine, sustained pattern (e.g. steadily rising engagement) from a one-off fluctuation tied to unusual circumstances in a single year', 'Multi-year tracking is prohibited by policy', 'Youth participation never changes meaningfully from year to year'], correct: 1, explanation: 'Looking at trends across multiple years helps distinguish a genuine, sustained pattern from a one-off fluctuation that might reflect unusual circumstances in just one particular year.' },
    { section: HN3, topic: HN3, stem: 'A talent-detection initiative identified 15 promising youth last year; 11 of them are still actively engaged in a relevant development pathway this year. What is the retention rate?', options: ['About 67%', 'About 73%', 'About 78%', 'About 82%'], correct: 1, explanation: '11 ÷ 15 ≈ 0.733, or about 73%.' },
    { section: HN3, topic: HN3, stem: 'Why is monitoring retention (not just initial identification) important for talent-detection and youth-engagement programmes?', options: ['Retention has no bearing on a programme’s real impact', 'Identifying talent initially is only the first step; sustained engagement over time is what actually translates into real skill development and opportunity', 'Only the initial identification moment ever matters', 'Tracking retention is prohibited by policy'], correct: 1, explanation: 'Initial identification is only a first step; sustained engagement over time is what actually produces real skill development and opportunity, making retention an important indicator of a programme’s genuine impact.' },
    { section: HN3, topic: HN3, stem: 'A Cell has 3 youth sports clubs with memberships of 22, 18 and 25. What is the combined membership across all three clubs?', options: ['60', '63', '65', '68'], correct: 2, explanation: '22 + 18 + 25 = 65.' },
    { section: HN4, topic: HN4, stem: 'What is the most appropriate first response if a social development officer becomes aware of a credible child-protection concern (e.g. suspected abuse or neglect) during fieldwork?', options: ['Investigate and resolve the matter personally with no referral', 'Follow the established child-protection referral process promptly, involving the appropriate authorities/services rather than handling it alone', 'Ignore it unless the child directly reports it in writing', 'Discuss the concern publicly in the community to raise awareness'], correct: 1, explanation: 'Credible child-protection concerns should be handled through the established referral process involving appropriate authorities and services promptly — not investigated alone, ignored pending formal written reports, or discussed publicly in ways that could harm the child or compromise the process.' },
    { section: HN4, topic: HN4, stem: 'Rwanda’s Isange One Stop Centers are primarily associated with which kind of service?', options: ['Business registration', 'Integrated support for survivors of gender-based violence and child abuse, combining medical, psychosocial, legal and police services in one location', 'Agricultural extension services', 'Tax collection'], correct: 1, explanation: 'Isange One Stop Centers provide integrated support for survivors of gender-based violence and child abuse, bringing together medical, psychosocial, legal and police services in one coordinated location.' },
    { section: HN4, topic: HN4, stem: 'Why is confidentiality particularly important when handling a child-protection case at Cell level?', options: ['Confidentiality has no particular importance in these cases', 'Protecting the identity and details of a vulnerable child (and the reporting party) helps prevent further harm, retaliation, or stigma, while the case is properly investigated through appropriate channels', 'Confidentiality should never apply to child-protection matters', 'Only adults’ privacy needs ever matter, not children’s'], correct: 1, explanation: 'Protecting the identity and details of a vulnerable child, and of whoever reported the concern, helps prevent further harm, retaliation or stigma while the matter is properly investigated through the appropriate channels.' },
    { section: HN4, topic: HN4, stem: 'A community member reports a concern about a child’s welfare but asks to remain anonymous. What is an appropriate response?', options: ['Refuse to act unless the reporter identifies themselves', 'Respect the request for anonymity where possible while still following the proper referral process to address the underlying concern', 'Publicly reveal who made the report', 'Dismiss the concern since it was reported anonymously'], correct: 1, explanation: 'Respecting a reporter’s request for anonymity where possible, while still following the proper process to investigate and address the underlying concern, balances protection of the reporter with appropriate action on the concern itself.' },
    { section: HN4, topic: HN4, stem: 'What is the relationship between community mobilisation and child protection, as both appear among this role’s duties?', options: ['The two are entirely unrelated', 'Community mobilisation can raise awareness of child-protection resources and encourage reporting of genuine concerns, supporting a more protective community environment', 'Mobilisation campaigns should never mention child protection', 'Child protection is solely a legal matter with no community-awareness dimension'], correct: 1, explanation: 'Community mobilisation on child protection can raise awareness of available resources and encourage appropriate reporting of genuine concerns, contributing to a more protective overall community environment.' },
    { section: HN4, topic: HN4, stem: 'A mobilisation campaign on child rights reaches 70 households, and a follow-up found 56 reported improved awareness of where to report concerns. What percentage reported improved awareness?', options: ['75%', '78%', '80%', '82%'], correct: 2, explanation: '56 ÷ 70 = 0.80, or 80%.' },
    { section: HN4, topic: HN4, stem: 'Why should an officer avoid making definitive judgements about a suspected child-protection case before proper investigation by the appropriate authorities?', options: ['Definitive judgement should always be made immediately on the officer’s own assessment', 'Premature conclusions could be wrong, cause harm to those involved, or compromise a proper investigation; the officer’s role is to refer appropriately, not to adjudicate the case', 'There is never any reason for caution in these cases', 'Only the reporting party’s judgement should be trusted, with no further investigation needed'], correct: 1, explanation: 'Premature conclusions risk being wrong, causing harm, or compromising a proper investigation; the officer’s appropriate role is prompt, proper referral — not personally adjudicating the case.' },
    { section: HN4, topic: HN4, stem: 'What is a reasonable way for an officer to build community trust around child-protection reporting over time?', options: ['Trust is irrelevant to effective child protection', 'Demonstrating consistent, respectful, confidential handling of concerns over time helps build the community’s confidence that reporting a concern will be taken seriously and handled appropriately', 'Publicising past cases widely builds trust', 'Trust-building has no practical value for this duty'], correct: 1, explanation: 'Consistently handling concerns respectfully and confidentially over time helps build community confidence that reports will be taken seriously and handled properly, encouraging appropriate future reporting.' },
    { section: HN4, topic: HN4, stem: 'A child-protection awareness session is held alongside a broader social-affairs community meeting. Why might this combined approach be practical?', options: ['Combining sensitive topics with general meetings is always inappropriate', 'It can reach a broad community audience efficiently, provided the sensitive content is handled appropriately and thoughtfully within that setting', 'Child protection should never be discussed in any group setting', 'This approach has no practical benefit'], correct: 1, explanation: 'Combining a child-protection awareness session with a broader community meeting can efficiently reach a wide audience, provided the sensitive content is handled thoughtfully and appropriately within that setting.' },
    { section: HN4, topic: HN4, stem: 'Why might an officer need to know the referral pathway for gender-based violence cases specifically, in addition to general child-protection referral processes?', options: ['These are identical processes requiring no separate knowledge', 'Gender-based violence cases may involve specific services (e.g. Isange One Stop Centers) and considerations distinct from general child-protection referrals, so knowing the specific pathway supports a more effective, appropriate response', 'Gender-based violence falls entirely outside this role’s relevant knowledge', 'Only police officers need to know any referral pathways'], correct: 1, explanation: 'Gender-based violence cases can involve specific services and considerations — such as Isange One Stop Centers — distinct from general child-protection referrals, so knowing the specific pathway supports a more effective response.' },
    { section: HN4, topic: HN4, stem: 'A Cell’s child-protection awareness materials were distributed to 180 households; a follow-up survey of 60 of those households found 51 could correctly describe how to report a concern. What percentage of the surveyed households could do so?', options: ['80%', '82%', '85%', '88%'], correct: 2, explanation: '51 ÷ 60 = 0.85, or 85%.' },
    { section: HN4, topic: HN4, stem: 'What is the most appropriate way to document a child-protection concern that has been referred to the appropriate authorities, balancing accountability with confidentiality?', options: ['Keep no record of any kind', 'Maintain an appropriately confidential, accurate record of the referral and key actions taken, accessible only to those with a legitimate need to know', 'Share full case details in the Cell’s general public report', 'Record only the reporter’s name with no other details'], correct: 1, explanation: 'A confidential, accurate record of the referral and key actions, accessible only to those with a legitimate need to know, balances accountability for proper handling with protecting the child’s and reporter’s privacy.' },
    { section: HN4, topic: HN4, stem: 'Why might community mobilisation on child rights specifically address positive discipline and non-violent parenting approaches?', options: ['These topics are unrelated to child protection', 'Promoting non-violent, positive approaches to child-rearing is a preventive measure that can reduce the risk of harm before a protection concern arises', 'Discussing parenting approaches is outside any legitimate scope for this role', 'Parenting practices have no bearing on child welfare outcomes'], correct: 1, explanation: 'Promoting positive, non-violent approaches to child-rearing is a preventive measure that can help reduce the risk of harm before a formal protection concern arises, fitting naturally within community mobilisation on child rights.' },
    { section: HN4, topic: HN4, stem: 'A social development officer is uncertain whether a specific situation meets the threshold for formal child-protection referral. What is the most appropriate action?', options: ['Assume it does not meet the threshold and take no action', 'Seek guidance from a supervisor or the appropriate child-protection focal point rather than deciding alone when genuinely uncertain', 'Wait indefinitely without seeking any guidance', 'Make a final decision alone with no consultation, regardless of uncertainty'], correct: 1, explanation: 'When genuinely uncertain, seeking guidance from a supervisor or the appropriate focal point is the responsible course of action, rather than deciding alone or simply taking no action due to uncertainty.' },
    { section: HN4, topic: HN4, stem: 'A child-rights community session had 95 attendees, of whom 19 asked a question afterward during the open discussion. What percentage of attendees asked a question?', options: ['18%', '20%', '22%', '24%'], correct: 1, explanation: '19 ÷ 95 = 0.20, or 20%.' },
    { section: HN4, topic: HN4, stem: 'Why does this role’s combination of social-protection, education, health and child-protection duties make strong "coordination" skills especially valuable?', options: ['Coordination skills have no particular relevance to this combination of duties', 'Many real situations span multiple domains at once (e.g. a vulnerable household with both an education and a child-protection dimension), so effectively coordinating across sectors and services is central to responding well', 'Each duty area is entirely separate with no overlap in practice', 'Coordination is only relevant for senior management roles'], correct: 1, explanation: 'Real situations often span multiple domains at once — for example, a vulnerable household facing both an education and a child-protection concern — so effectively coordinating across sectors and services is central to handling such cases well.' },
    { section: HN4, topic: HN4, stem: 'What is the best summary of this role’s appropriate relationship to formal law-enforcement or judicial processes in a child-protection case?', options: ['The officer should always personally lead any investigation or judicial process', 'The officer’s role is typically to identify concerns, refer appropriately, and support the process, while formal investigation and judicial processes are handled by the appropriate specialised authorities', 'The officer should have no involvement in child-protection cases of any kind', 'Formal processes are irrelevant once a referral has been made'], correct: 1, explanation: 'The officer’s role is to identify concerns, make appropriate referrals and support the broader process — while formal investigation and judicial functions remain with the appropriately specialised authorities, not the social development officer personally.' },
    { section: HN3, topic: HN3, stem: 'A youth innovation hub reports that 14 of 40 participating youth went on to start a small income-generating activity within six months. What percentage is this?', options: ['30%', '32%', '35%', '38%'], correct: 2, explanation: '14 ÷ 40 = 0.35, or 35%.' },
    { section: HN3, topic: HN3, stem: 'Why might an officer encourage a promising young innovator to connect with an existing cooperative or business-support structure, rather than working in isolation?', options: ['Connecting with existing structures never adds any value', 'Established cooperatives or business-support structures can offer mentorship, resources, or market access the officer alone cannot provide, strengthening the young person’s chances of success', 'Isolation is always the better approach for young innovators', 'This kind of connection is outside the role’s relevant scope entirely'], correct: 1, explanation: 'Established structures such as cooperatives or business-support services can provide mentorship, resources or market access beyond what the officer alone could offer, improving the young innovator’s chances of success.' },
    { section: HN4, topic: HN4, stem: 'A mobilisation campaign on child rights is planned to coincide with a national awareness day. Why might this timing be a reasonable choice?', options: ['National awareness days have no relevance to local campaigns', 'Aligning with a national awareness day can amplify messaging through existing national attention and materials, supporting a more impactful local campaign', 'Timing around national events should always be avoided', 'This coordination is prohibited by policy'], correct: 1, explanation: 'Aligning a local campaign with a national awareness day can amplify its messaging by leveraging existing national attention and materials, supporting a more impactful local effort.' },
    { section: HN4, topic: HN4, stem: 'Of 130 households reached by a child-protection awareness campaign, 104 said they would know how to report a concern afterward. What percentage is this?', options: ['76%', '78%', '80%', '82%'], correct: 2, explanation: '104 ÷ 130 = 0.80, or 80%.' },
    { section: HN4, topic: HN4, stem: 'Why is it important for an officer to be aware of signs that may indicate a child is experiencing neglect or abuse, even without being a trained child-protection specialist?', options: ['Awareness of such signs is unnecessary for this role', 'Basic awareness supports earlier identification and timely, appropriate referral, which can be critical to a child’s safety and wellbeing', 'Only specialists should ever be aware of these signs', 'Early identification has no bearing on outcomes for the child'], correct: 1, explanation: 'Basic awareness of warning signs — without requiring specialist expertise — supports earlier identification and timely referral, which can be critical to protecting a child’s safety and wellbeing.' },
    { section: HN4, topic: HN4, stem: 'What is a reasonable approach if a child-protection referral the officer made does not appear to have been acted on after a reasonable period?', options: ['Assume nothing further can be done and drop the matter', 'Follow up through the appropriate channel to check on the referral’s status, consistent with the officer’s duty to support the process', 'Handle the case personally instead, bypassing the formal process', 'Make the case public to pressure action'], correct: 1, explanation: 'Following up through the appropriate channel to check on a referral’s status is consistent with the officer’s supportive role in the process — not abandoning the matter, bypassing proper channels, or making it public.' },
    { section: HN4, topic: HN4, stem: 'A Cell runs 4 child-rights mobilisation sessions this year, reaching 85, 92, 78 and 103 attendees respectively. What is the total reach across all four sessions?', options: ['348', '355', '358', '362'], correct: 2, explanation: '85 + 92 + 78 + 103 = 358.' },
    { section: HN4, topic: HN4, stem: 'Why might involving trusted community or religious leaders in child-rights mobilisation (where appropriate) help reinforce the message?', options: ['Such leaders have no influence on community attitudes', 'Trusted local leaders can lend credibility and help reinforce messages in ways that resonate with community norms and values, supporting broader acceptance', 'Involving community leaders in this topic is prohibited', 'Only government officials should ever discuss child rights'], correct: 1, explanation: 'Trusted community or religious leaders can lend credibility and help reinforce child-rights messages in ways that resonate with local norms and values, supporting broader community acceptance.' },
    { section: HN4, topic: HN4, stem: 'What best reflects the appropriate balance between vigilance and avoiding unwarranted suspicion when monitoring for child-protection concerns in the community?', options: ['Treat every household as a potential case requiring formal investigation', 'Stay attentive to genuine warning signs and credible concerns, responding proportionately and through proper channels, without assuming the worst of every family without cause', 'Ignore all potential warning signs to avoid being seen as intrusive', 'Only act if a case is reported in writing with a formal signature'], correct: 1, explanation: 'The appropriate balance is staying genuinely attentive to credible warning signs and responding proportionately through proper channels — neither treating every household with suspicion nor ignoring real warning signs out of excessive caution.' },
    { section: HN4, topic: HN4, stem: 'A district trains 18 Cell-level officers on updated child-protection referral procedures; 15 complete the full training. What percentage completed it?', options: ['78%', '80%', '83%', '85%'], correct: 2, explanation: '15 ÷ 18 ≈ 0.833, or about 83%.' },
  ],
};

