  authority: 'MINALOC',
  slug: 'human-capital-social-development-officer-mock-exam-5',
  title: 'Human Capital & Social Development Officer — Mock Exam 5',
  summary: 'A mixed-practice mock spanning every area of this role—social protection, education, health, youth, governance and ethics—plus a linked case study and analytical/numerical reasoning.',
  free: false,
  difficulty: 'STANDARD',
  minutes: 120,
  sections: [{ name: MX1 }, { name: MX2 }, { name: 'Case study', label: CASE_LABEL }, { name: MX3 }],
